-- sql/2026-08-28_objets_dd2024_sp-im9a.sql
-- SP-IM9a — Redressement des objets magiques DD2024 rapprochés du SRD.
--
-- Source : FR_SRD_CC_v5.2.1-objets_magiques.pdf, section « Objets magiques de A à Z ».
--
-- CONTEXTE : ces objets ont été importés par un script antérieur qui a remplacé
-- la description de chaque objet par un RÉSUMÉ, et n'a renseigné ni la rareté ni
-- l'harmonisation. Relevé en base le 2026-08-28, sur 359 objets DD2024 :
--   * om_rarete = 0 sur 349 d'entre eux — valeur qui n'existe PAS dans
--     dd_objets_magiques_rarete, dont les ids commencent à 1 ;
--   * om_harmonisation = 1 sur 6 seulement, là où le SRD en marque ~129 ;
--   * 186 descriptions à moins de 80 % de la longueur du texte d'origine ;
--   * 8 catégories fausses (élixirs et huiles rangés en « Objets merveilleux »
--     au lieu de « Potions », fers de cheval en « Armes »…).
--
-- Le SRD est parfaitement régulier : chaque objet porte une ligne de type
-- « <Catégorie>, <rareté> (Harmonisation requise …) » d'où les trois paramètres
-- se déduisent mécaniquement. C'est cette ligne qui fait foi ici.
--
-- PÉRIMÈTRE : les 235 objets de la source 93 dont le nom se rapproche d'une entrée
-- du SRD. Sont EXCLUS :
--   * les objets des sources 91 (MdJ) et 95 (supplément de l'utilisateur) ;
--   * les déclinaisons d'entrées génériques — « Anneau de résistance (feu) »,
--     « Pierre de Ioun — Agilité », « Arme +2 »… → SP-IM9b ;
--   * la DESCRIPTION des 16 objets dont le texte du SRD porte une table : elle
--     est laissée en l'état (om_description non modifiée) en attendant que les
--     tables soient saisies dans dd_tableaux → SP-IM9c. Leur rareté, leur
--     harmonisation et leur catégorie sont corrigées dès maintenant.
--
-- « rareté variable » (Potions de guérison, Parchemin de sort…) laisse om_rarete
-- inchangé : la rareté dépend de la déclinaison, elle est traitée en SP-IM9b.
--
-- Quand le SRD précise avec QUI l'harmonisation doit être faite (« avec un Clerc,
-- Druide ou Paladin »), la base n'ayant qu'un booléen, la précision est conservée
-- en tête de description.
--
-- IDEMPOTENCE : UPDATE ciblés par om_id via une table temporaire. Rejouable.

-- ------------------------------------------------------------
-- Redressement de 235 objets
-- ------------------------------------------------------------

DROP TEMPORARY TABLE IF EXISTS tmp_om_im9a;

CREATE TEMPORARY TABLE tmp_om_im9a (
  t_id    INT UNSIGNED NOT NULL PRIMARY KEY,
  t_cat   INT UNSIGNED NULL,
  t_rar   TINYINT      NULL,
  t_har   TINYINT      NOT NULL,
  t_desc  TEXT         NULL
) ENGINE=InnoDB;


UPDATE dd_objets_magiques o
  JOIN tmp_om_im9a t ON t.t_id = o.om_id
SET o.om_com_id        = COALESCE(t.t_cat,  o.om_com_id),
    o.om_rarete        = COALESCE(t.t_rar,  o.om_rarete),
    o.om_harmonisation = t.t_har,
    o.om_description   = COALESCE(t.t_desc, o.om_description);

DROP TEMPORARY TABLE tmp_om_im9a;
