INSERT INTO tmp_om_im9a (t_id, t_cat, t_rar, t_har, t_desc) VALUES
  (1311, 38, 2, 1, '<p>Tant que vous portez cette amulette, vous ne pouvez ni être la cible d’un sort de divination ni perçu par un capteur de scrutation, sauf si vous le permettez.</p>'),
  (1312, 38, 2, 1, '<p>Tant que vous portez ce pendentif, vous pouvez entreprendre l’action Magie pour récupérer 2d4 + 2 points de vie. Une fois utilisée, cette propriété ne peut plus resservir avant l’aube suivante.</p><p>Tant que vous portez ce pendentif, vous bénéficiez en outre de l’Avantage aux jets de sauvegarde visant à éviter l’état Empoisonné ou à y mettre fin.</p>'),
  (1313, 38, 2, 1, '<p>Tant que vous portez ce pendentif, vous recevez les bénéfices ci-après.</p><p><b>Préservation de la vie.</b> Chaque fois que vous effectuez un jet de sauvegarde contre la mort, vous pouvez transformer un résultat de 9 ou moins en 10, transformant ainsi un échec en réussite.</p><p><b>Stimulation de la guérison.</b> Chaque fois que vous lancez un dé de vie pour récupérer des points de vie, vous doublez le nombre de points de vie que ce dé vous octroie.</p>'),
  (1314, 38, 3, 1, '<p>Cette chaîne en argent délicatement ouvragée porte en sautoir une gemme noire magnifiquement taillée. Tant que vous la portez, vous bénéficiez de l’Immunité contre l’état Empoisonné et les dégâts de poison.</p>'),
  (1315, 38, 3, 1, '<p>Votre Constitution est de 19 tant que vous portez cette amulette. Elle est sans effet sur vous si votre Constitution est déjà supérieure ou égale à 19.</p>'),
  (1316, 38, 4, 1, NULL),
  (1179, 33, 3, 1, '<p>Tant que vous portez cet anneau, le Terrain difficile ne vous coûte aucun déplacement supplémentaire. En outre, aucune magie ne peut réduire vos Vitesses ni vous imposer l’état Paralysé ou Entravé.</p>'),
  (1180, 33, 3, 1, '<p>Cet anneau dispose de 3 charges et récupère quotidiennement 1d3 charges dépensées, à l’aube. Lorsque vous ratez un jet de sauvegarde de Dextérité en portant l’anneau, vous pouvez jouer votre Réaction pour dépenser 1 charge et finalement réussir ce JS.</p>'),
  (1181, 33, 3, 0, '<p>Cet anneau dispose de 3 charges et récupère quotidiennement 1d3 charges dépensées, à l’aube. Tant que vous portez l’anneau, vous pouvez en dépenser 1 charge pour lancer l’un des sorts suivants (DD de sauvegarde 13) par son intermédiaire :</p><ul><li>amitié avec les animaux</li><li>terreur (affecte uniquement les Bêtes)</li><li>communication avec les animaux</li></ul>'),
  (1182, 33, 5, 1, '<p>Tant que vous portez cet anneau, vous pouvez entreprendre l’action Magie pour recevoir l’état Invisible. Vous restez Invisible jusqu’à ce que l’anneau soit retiré ou que vous entrepreniez une action Bonus pour redevenir visible.</p>'),
  (1183, 33, 2, 1, '<p>Tant que vous portez cet anneau, vous êtes immunisé contre toute magie permettant à une autre créature de lire vos pensées, de déterminer si vous mentez, de connaître votre alignement ou de découvrir votre type de créature. Les créatures ne peuvent communiquer par télépathie avec vous que si vous les y autorisez.</p><p>Vous pouvez entreprendre l’action Magie pour que l’anneau devienne imperceptible jusqu’à ce que vous le rendiez à nouveau perceptible au prix d’une autre action Magie (ou que vous retiriez l’anneau, ou encore que vous mouriez).</p><p>Si vous mourez en portant l’anneau, votre âme vient l’habiter, à moins qu’il abrite déjà une autre âme. Vous pouvez choisir de demeurer dans l’anneau ou de partir pour l’au-delà. Tant que votre âme réside dans l’anneau, vous pouvez communiquer par télépathie avec la créature qui le porte. Le porteur ne peut rien faire pour empêcher cette communication télépathique.</p>'),
  (1184, 33, 2, 1, '<p>Si vous subissez des dégâts de froid alors que vous portez l’anneau, il réduit ces dégâts de 2d8.</p><p>En outre et tant que vous portez cet anneau, vous-même et tout ce que vous portez êtes insensibles aux effets délétères des températures inférieures ou égales à –18 °C.</p>'),
  (1185, 33, 5, 1, '<p>Tant que vous portez cet anneau, vous pouvez entreprendre l’action Magie pour convoquer un djinn spécifique originaire du Plan Élémentaire de l’Air. Ce djinn apparaît en un espace inoccupé de votre choix, dans un rayon de 36 m de vous. Il reste aussi longtemps que vous maintenez la Concentration, jusqu’à un maximum de 1 heure, mais disparaît s’il tombe à 0 point de vie.</p><p>Ainsi convoqué, le djinn est Amical envers vous et vos compagnons, et il se soumet à vos ordres. En l’absence d’instructions précises, le djinn se défend contre les assaillants mais n’entreprend aucune autre action.</p><p>Après le départ du djinn, il ne peut plus être convoqué pendant 24 heures et l’anneau devient non magique si ce djinn meurt.</p><p>Les anneaux de convocation de djinn sont souvent créés par les djinns qu’ils invoquent, puis offerts aux mortels en gage d’amitié ou d’estime.</p>'),
  (1186, 33, 4, 1, '<p>Vous pouvez lancer lumières dansantes ou lumière par le biais de l’anneau.</p><p>L’anneau dispose de 6 charges et récupère quotidiennement 1d6 charges dépensées, à l’aube. Vous pouvez en dépenser les charges pour utiliser les propriétés ci-dessous.</p><p><b>Étoiles filantes.</b> Vous pouvez dépenser 1 à 3 charges au prix de l’action Magie. Pour chaque charge dépensée, vous faites jaillir une particule de lumière incandescente depuis l’anneau vers un point que vous voyez dans un rayon de 18 m. Chaque créature prise dans un Cube de 4,50 m ayant ce point pour origine subit une pluie d’étincelles. Elle effectue un jet de sauvegarde de Dextérité DD 15 et subit 5d4 dégâts radiants en cas d’échec, la moitié en cas de réussite.</p><p><b>Lueurs féeriques.</b> Dépensez 1 charge pour lancer lueurs féeriques par l’anneau.</p><p><b>Sphères de foudre.</b> Dépensez 2 charges au prix de l’action Magie pour créer un maximum de quatre sphères de foudre de 90 cm de diamètre.</p><p>Chaque sphère apparaît en un espace inoccupé que vous voyez, dans un rayon de 36 m. Les sphères persistent tant que vous maintenez votre Concentration, jusqu’à 1 minute. Chaque sphère émet une Lumière faible dans un rayon de 9 m.</p><p>Par une action Bonus, vous pouvez déplacer chaque sphère d’un maximum de 9 m à condition qu’elles restent dans un rayon de 36 m de vous. La première fois qu’une sphère arrive à 1,50 m ou moins d’une créature autre que vous et que celle-ci ne bénéficie pas d’un Abri total, la sphère libère un éclair sur la créature et disparaît. Cette créature effectue un jet de sauvegarde de Dextérité DD 15. En cas d’échec, elle subit des dégâts de foudre dépendant du nombre de sphères créées, comme indiqué sur la table suivante. En cas de réussite, la créature subit la moitié de ces dégâts.</p><p>Nombre de Dégâts de sphères foudre</p><p>Nombre de Dégâts de sphères foudre</p><p>4d12</p><p>2d6</p><p>5d4</p><p>2d4</p>'),
  (1187, 33, 3, 1, '<p>Quand vous tombez alors que vous portez cet anneau, vous descendez de 18 m par round sans subir de dégâts de chute.</p>'),
  (1192, 33, 2, 0, '<p>Tant que vous portez cet anneau, vous lancez marche sur l’onde par son biais, en ne ciblant que vous-même.</p>'),
  (1193, 33, 2, 0, '<p>Tant que vous portez cet anneau, vous disposez d’une Vitesse de nage de 12 m.</p>'),
  (1194, 33, 3, 1, '<p>Vous recevez un bonus de +1 à la CA et aux jets de sauvegarde tant que vous portez cet anneau.</p>'),
  (1195, 33, 3, 1, '<p>Tant que vous portez cet anneau, vous pouvez entreprendre l’action Magie pour recevoir la vision aux rayons X sur 9 m pendant 1 minute. Pour vous, les objets solides dans ce rayon apparaissent transparents et ne bloquent pas la lumière. Cette vision pénètre 30 cm de pierre, 2,5 cm de métal courant et jusqu’à 90 cm de bois ou de terre. Des substances plus denses ou une fine feuille de plomb bloquent la vision.</p><p>Chaque fois que vous réutilisez cet anneau sans avoir pris de Repos long, vous devez réussir un jet de sauvegarde de Constitution DD 15 sous peine de recevoir un niveau d’Épuisement.</p>'),
  (1196, 33, 4, 1, '<p>Tant que vous portez cet anneau, vous récupérez 1d6 points de vie toutes les 10 minutes à condition qu’il vous reste au moins 1 point de vie. Si vous perdez une partie de votre corps, l’anneau fait repousser la partie manquante qui retrouve ses pleines fonctions au bout de 1d6 + 1 jours, à condition que vous conserviez au moins 1 point de vie pendant tout ce temps.</p>'),
  (1197, 33, 5, 1, '<p>Tant que vous portez cet anneau, vous avez l’Avantage aux jets de sauvegarde contre les sorts. Si vous réussissez le JS contre un sort du 7e niveau ou inférieur, ce sort n’a aucun effet sur vous. Si ce sort ne ciblait que vous sans créer de zone d’effet, vous pouvez jouer votre Réaction pour le retourner vers son lanceur ; l’incantateur effectue un JS contre le sort en prenant son propre DD de sauvegarde des sorts.</p>'),
  (1208, 33, 2, 1, '<p>Tant que vous portez cet anneau, vous pouvez lancer saut par son intermédiaire, mais vous ne pouvez cibler que vous-même.</p>'),
  (1209, 33, 3, 1, '<p>Cet anneau stocke les sorts qui sont lancés sur lui et les conserve jusqu’à ce que le porteur harmonisé les utilise. L’anneau peut stocker jusqu’à 5 niveaux de sort à la fois. Quand on le trouve, il contient 1d6 − 1 niveaux de sort choisis par le MJ.</p><p>Toute créature peut lancer un sort du 1er au 5e niveau dans l’anneau à condition de le toucher au moment de l’incantation. Le sort ne produit aucun effet hormis celui d’être stocké dans l’anneau. Si l’anneau ne peut pas contenir ce sort, celui-ci est dépensé sans effet. Le niveau de l’emplacement utilisé pour lancer le sort détermine la quantité d’espace qu’il utilise.</p><p>Tant que vous portez cet anneau, vous pouvez lancer l’un des sorts qui y sont stockés. Ce sort utilise le niveau d’emplacement de sort, le DD de sauvegarde des sorts, le bonus d’attaque de sort et la caractéristique d’incantation de l’incantateur d’origine, mais il est par ailleurs traité comme si vous le lanciez. Le sort lancé par l’anneau n’y est plus stocké et libère l’espace correspondant.</p>'),
  (1210, 33, 4, 1, '<p>Tant que vous portez cet anneau, vous pouvez lancer télékinésie par son intermédiaire.</p>'),
  (1211, 33, 5, 0, '<p>Tant que vous portez cet anneau, vous pouvez dépenser 1 de ses 3 charges pour lancer souhait par son biais. L’anneau devient non magique lorsque vous dépensez sa dernière charge.</p>'),
  (1212, 33, 3, 1, '<p>Cet anneau dispose de 3 charges et récupère quotidiennement 1d3 charges dépensées, à l’aube. Tant que vous le portez, vous pouvez entreprendre l’action Magie pour en dépenser 1 à 3 charges et effectuer une attaque de sort à distance contre une créature que vous voyez dans un rayon de 18 m. L’anneau produit une tête de bélier spectrale et effectue son jet d’attaque avec un bonus de +7. Si l’attaque touche, la cible subit 2d10 dégâts de force pour chaque charge dépensée, et elle est repoussée de 1,50 m de vous.</p><p>Au lieu de cela, vous pouvez dépenser 1 à 3 des charges de l’anneau au prix de l’action Magie pour tenter de briser un objet non magique que vous voyez dans un rayon de 18 m, à condition qu’il ne soit porté par personne. L’anneau effectue un test de Force avec un bonus de +5 par charge dépensée.</p>'),
  (1213, 34, 4, 1, '<p>Vous recevez un bonus de +1 aux jets d’attaque et de dégâts effectués avec cette arme magique, qui n’a pas de corde. Chaque fois que vous faites le geste de tendre l’arc, une flèche magique faite d’énergie dorée apparaît, prête à être décochée. Les flèches produites par cette arme infligent des dégâts de force au lieu des dégâts perforants si l’attaque touche, et s’évanouissent après avoir touché ou raté leur cible. Jusqu’à sa disparition, une telle flèche émet une Lumière vive dans un rayon de 6 m et une Lumière faible sur 6 m de plus.</p><p>L’arme est dotée des propriétés supplémentaires suivantes.</p><p><b>Échelle d’énergie.</b> Au prix de l’action Magie, vous décochez une volée de flèches d’énergie pure avec cette arme en direction d’un mur situé dans un rayon de 18 m. Les flèches se transforment en barreaux lumineux qui dépassent du mur, formant une échelle magique pouvant atteindre 18 m de haut. Cette échelle persiste pendant 1 minute avant de disparaître.</p><p><b>Flèche d’entrave.</b> Chaque fois que vous utilisez cette arme pour effectuer une attaque à distance contre une créature, vous pouvez tenter d’entraver la cible au lieu de lui infliger des dégâts. Si la flèche touche, la cible doit réussir un jet de sauvegarde de Force DD 15 sous peine de subir l’état Entravé pendant 1 minute. Au prix d’une action, toute créature Entravée par une flèche peut effectuer un test de Force (Athlétisme) DD 20 pour tenter de se libérer, et met fin à l’effet sur ellemême en cas de réussite.</p><p><b>Flèche de transport.</b> Au prix de l’action Magie, vous décochez avec cette arme une flèche d’énergie sur une cible que vous voyez dans un rayon de 18 m. La cible peut être une créature consentante de taille M ou inférieure ou un objet qui n’est porté par personne, à condition que celui-ci contienne dans un Cube de 1,50 m. La flèche téléporte la cible en un espace inoccupé que vous voyez, dans un rayon de 3 m de vous.</p>'),
  (1214, 34, 4, 1, '<p>Lorsque vous encochez une flèche sur cet arc, il murmure en elfique « Une prompte défaite pour mes ennemis. » Lorsque vous utilisez l’arme pour effectuer une attaque à distance, vous pouvez prononcer ou signer les mots de commande suivants : « Une mort rapide à toi qui m’as fait du tort. » La cible devient votre ennemi désigné et le reste pendant 7 jours, jusqu’à l’aube du dernier jour. Elle ne l’est plus si elle meurt dans l’intervalle. Vous ne pouvez avoir qu’un seul ennemi désigné de ce type à la fois. Lorsque votre ennemi désigné meurt, vous pouvez en désigner un nouveau après l’aube suivante.</p><p>Lorsque vous effectuez un jet d’attaque à distance avec cette arme contre votre ennemi désigné, vous bénéficiez de l’Avantage sur le jet. De plus, votre cible ne reçoit aucun bénéfice lié à un Abri partiel ou supérieur, et vous ne subissez aucun Désavantage dû à la portée longue. Si l’attaque touche, votre ennemi désigné subit 3d6 dégâts perforants supplémentaires.</p><p>Tant que votre ennemi désigné est vivant, vous subissez le Désavantage aux jets d’attaque avec toutes les autres armes.</p>'),
  (1218, 34, 3, 1, '<p>Tant que vous tenez cette arme magique, vous pouvez, par une action Bonus et en prononçant son mot de commande, susciter des flammes autour de la partie de l’arme qui inflige des dégâts. Ces flammes projettent une Lumière vive sur un rayon de 12 m et une Lumière faible sur 12 m de plus. Tant que l’arme est nimbée de flammes, elle inflige 2d6 dégâts de feu supplémentaires si l’attaque touche. Ces flammes persistent jusqu’à ce que, par une action Bonus, vous réitériez le mot de commande ou que vous lâchiez, rangiez ou rengainiez l’arme.</p>'),
  (1219, 34, 3, 0, '<p>Cette arme magique inflige 2d6 dégâts supplémentaires à toute créature qu’elle touche. Ces dégâts supplémentaires sont du même type que les dégâts normaux de l’arme.</p>'),
  (1220, 34, 2, 1, '<p>Tant que cette arme est à portée d’allonge et que persiste votre Harmonisation avec elle, vous-même et vos alliés dans un rayon de 9 m recevez les bénéfices suivants.</p><p><b>Alarme.</b> L’arme réveille magiquement chaque sujet endormi lorsqu’un combat commence. Ce bénéfice ne tire pas un sujet d’un sommeil provoqué magiquement.</p><p><b>Vigilance surnaturelle.</b> Chaque sujet a l’Avantage aux jets d’Initiative.</p>'),
  (1254, 35, 4, 1, '<p>Chaque armure d’écailles de dragon est faite avec des écailles d’une espèce de dragon. Il arrive à certains dragons de rassembler leurs écailles tombées pour en faire don. En d’autres occasions, ces écailles sont prélevées avec soin sur le cadavre d’un dragon tué par des chasseurs. Dans tous les cas, une armure d’écailles de dragon est un bien inestimable.</p><p>Tant que vous portez cette armure, vous recevez un bonus de +1 à la CA, bénéficiez de l’Avantage aux jets de sauvegarde contre le souffle des Dragons, et de la Résistance à un type de dégâts déterminé par l’espèce de dragon qui a fourni les écailles (cf. table ci-après).</p><p>Au prix de l’action Magie, vous pouvez en outre focaliser vos sens afin de percevoir à quelle distance et dans quelle direction se trouve le plus proche dragon de l’espèce correspondant à l’armure dans un rayon de 45 km. Cette action ne peut alors plus resservir avant l’aube suivante.</p><p>Dragon</p><p>Résistance Dragon Résistance</p><p>Airain</p><p>Feu</p><p>Cuivre</p><p>Acide</p><p>Argent</p><p>Froid</p><p>Noir</p><p>Acide</p><p>Blanc</p><p>Froid</p><p>Or</p><p>Feu</p><p>Bleu</p><p>Foudre</p><p>Rouge</p><p>Feu</p><p>Bronze</p><p>Foudre</p><p>Vert</p><p>Poison</p>'),
  (1255, 35, 5, 1, '<p>Vous bénéficiez de la résistance aux dégâts contondants, perforants et tranchants tant que vous portez cette armure.</p><p>Carapace métallique. Vous pouvez entreprendre l’action Magie pour vous octroyer l’Immunité contre les dégâts contondants, perforants et tranchants pendant 10 minutes (l’effet prend prématurément fin si vous ne portez plus l’armure). Une fois cette propriété utilisée, vous ne pouvez plus y recourir avant l’aube suivante.</p><p>Armure de cuir clouté enchantée</p><p>Armure (armure de cuir clouté) rare</p><p>Tant que vous portez cette armure, vous recevez un bonus de +1 à la CA. Par une action Bonus, vous faites prendre à l’armure l’apparence de vêtements ordinaires ou d’un autre type d’armure. Vous décidez de son aspect, y compris sa couleur, son style et ses accessoires, mais l’armure conserve son encombrement normal et son poids. L’apparence illusoire persiste jusqu’à ce que vous réutilisiez cette propriété ou ôtiez l’armure.</p>'),
  (1257, 35, 3, 0, '<p>Vous recevez un bonus de +1 à la CA tant que vous portez cette armure. Vous êtes considéré comme formé au port de cette armure même s’il vous manque la formation aux armures lourdes et intermédiaires.</p>'),
  (1258, 35, 2, 0, '<p>Le mithral est un métal léger et souple. Une armure fabriquée dans ce matériau peut être portée sous des vêtements normaux. Si l’armure dans sa version normale impose le Désavantage aux tests de Dextérité (Discrétion) ou requiert une valeur de Force minimale, ce n’est pas le cas de la version en mithral.</p>'),
  (1269, 35, 3, 1, '<p>Tant que vous portez cette armure, vous bénéficiez de la résistance à l’un des types de dégâts suivants : contondants, perforants ou tranchants. Le MJ choisit ce type ou laisse le hasard en décider.</p><p>Malédiction. Cette armure est maudite, un fait qui n’est révélé que lorsque le sort identification est lancé sur l’armure ou quand vous vous harmonisez avec elle. S’harmoniser avec l’armure vous maudit jusqu’à ce que vous soyez la cible du sort délivrance des malédictions ou d’un effet magique équivalent ; ôter l’armure ne suffit pas à lever cette malédiction. Tant que cette malédiction vous affecte, vous subissez la Vulnérabilité à deux des trois types de dégâts associés à l’armure (autres que celui auquel elle octroie une résistance).</p>'),
  (1270, 35, 4, 1, '<p>Tant que vous portez cette armure, vous recevez un bonus de +1 à la CA et parlez l’abyssal. Les gantelets griffus de l’armure permettent en outre à vos attaques à mains nues d’infliger 1d8 dégâts tranchants au lieu des dégâts contondants habituels, et vous recevez un bonus de +1 aux jets d’attaque et de dégâts de vos attaques à mains nues.</p><p>Malédiction. Une fois cette armure maudite enfilée, vous ne pouvez plus l’ôter sauf si vous êtes la cible du sort délivrance des malédictions ou d’une magie équivalente. Tant que vous portez cette armure, vous subissez le Désavantage aux jets d’attaque contre les démons et aux jets de sauvegarde contre leurs sorts et aptitudes spéciales.</p>'),
  (1271, 35, 2, 0, '<p>Les parties en adamantium, l’un des matériaux les plus résistants qui existent, augmentent la solidité de cette armure. Tant que vous la portez, tout Coup critique contre vous devient un coup normal.</p>'),
  (1283, 36, 3, 1, '<p><em>Harmonisation requise avec un incantateur</em></p><p>Cette baguette dispose de 7 charges. Lorsque vous la tenez, vous pouvez dépenser jusqu’à 3 charges pour lancer éclair (DD de sauvegarde 15). Avec 1 charge, vous lancez le sort au 3e niveau. Vous augmentez le niveau du sort d’un cran par charge additionnelle dépensée.</p><p>Récupération des charges. La baguette récupère quotidiennement 1d6 + 1 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, la baguette se réduit en cendres, à jamais détruite.</p>'),
  (1284, 36, 3, 1, '<p><em>Harmonisation requise avec un incantateur</em></p><p>Cette baguette dispose de 7 charges. Lorsque vous la tenez, vous pouvez dépenser jusqu’à 3 charges pour lancer boule de feu (DD de sauvegarde 15). Avec 1 charge, vous lancez le sort au 3e niveau. Vous augmentez le niveau du sort d’un cran par charge additionnelle dépensée.</p><p>Récupération des charges. La baguette récupère quotidiennement 1d6 + 1 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, la baguette se réduit en cendres, à jamais détruite.</p>'),
  (1285, 36, 3, 1, '<p>Cette baguette dispose de 7 charges. Lorsque vous la tenez, vous pouvez entreprendre l’action Magie pour dépenser 1 charge. Pendant 1 minute, vous connaissez la direction dans laquelle se trouve la créature Hostile la plus proche dans un rayon de 18 m, mais pas la distance qui vous en sépare. La baguette détecte la présence de créatures Hostiles qui sont éthérées, Invisibles, déguisées ou cachées, ainsi que celles exposées à la vue de tous. L’effet se termine si vous cessez de tenir la baguette.</p><p>Récupération des charges. La baguette récupère quotidiennement 1d6 + 1 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, la baguette se réduit en cendres, à jamais détruite.</p>'),
  (1286, 36, 2, 0, '<p>Cette baguette dispose de 3 charges. Lorsque vous la tenez, vous pouvez dépenser 1 charge pour lancer détection de la magie par son biais. La baguette récupère quotidiennement 1d3 charges dépensées, à l’aube.</p>'),
  (1287, 36, 4, 1, '<p><em>Harmonisation requise avec un incantateur</em></p><p>Cette baguette dispose de 7 charges. Lorsque vous la tenez, vous pouvez dépenser 1 charge pour lancer métamorphose (DD de sauvegarde 15) par son biais.</p><p>Récupération des charges. La baguette récupère quotidiennement 1d6 + 1 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, la baguette se réduit en cendres, à jamais détruite.</p>'),
  (1288, 36, 3, 1, '<p><em>Harmonisation requise avec un incantateur</em></p><p>Cette baguette dispose de 7 charges. Tant que vous la tenez, vous pouvez entreprendre l’action Magie pour dépenser 1 de ses charges afin de produire un fin rayon bleuté qui jaillit de la pointe vers une créature que vous voyez dans un rayon de 18 m. La cible doit réussir un jet de sauvegarde de Constitution DD 15 sous peine de subir l’état Paralysé pendant 1 minute. À la fin de chacun de ses tours, la cible réitère le JS et met un terme à l’effet sur elle-même en cas de réussite.</p><p>Récupération des charges. La baguette récupère quotidiennement 1d6 + 1 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, la baguette se réduit en cendres, à jamais détruite.</p>'),
  (1290, 36, 3, 1, '<p>Cette baguette dispose de 7 charges. Sorts. Lorsque vous tenez la baguette, vous pouvez lancer l’un des sorts de la table suivante (DD de sauvegarde 15). La table indique le nombre de charges à dépenser pour lancer le sort.</p><p>Sort injonction (« fuis » ou « rampe » uniquement) terreur (Cône de 18 m)</p><p>Coût en charges</p><p>Récupération des charges. La baguette récupère quotidiennement 1d6 + 1 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, la baguette se réduit en cendres, à jamais détruite.</p>'),
  (1291, 36, 3, 1, '<p>Cette baguette dispose de 7 charges. Sorts. Lorsque vous tenez la baguette, vous pouvez lancer l’un des sorts de la table suivante (DD de sauvegarde 17). La table indique le nombre de charges à dépenser pour lancer le sort.</p><p>Sort immobilisation de monstre</p><p>Coût en charges immobilisation de personne</p><p>Récupération des charges. La baguette récupère quotidiennement 1d6 + 1 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, la baguette se réduit en cendres, à jamais détruite.</p>'),
  (1292, 36, 3, 1, NULL),
  (1293, 36, 2, 0, '<p>Cette baguette dispose de 3 charges et récupère quotidiennement 1d3 charges dépensées, à l’aube. Tant que vous la tenez, vous pouvez entreprendre l’action Magie pour dépenser 1 charge ; si un passage secret ou un piège se trouve dans un rayon de 18 m de vous, la baguette émet des impulsions et pointe en direction de l’élément détecté le plus proche.</p>'),
  (1294, 36, 2, 1, '<p><em>Harmonisation requise avec un incantateur</em></p><p>Cette baguette dispose de 7 charges. Lorsque vous la tenez, vous pouvez dépenser 1 charge pour lancer toile d’araignée (DD de sauvegarde 13).</p><p>Récupération des charges. La baguette récupère quotidiennement 1d6 + 1 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, la baguette se réduit en cendres, à jamais détruite.</p>'),
  (1317, 38, 2, 1, '<p>Ce balai en bois remplit la fonction de balai ordinaire jusqu’à ce que vous le chevauchiez et entrepreniez l’action Magie pour le placer en vol stationnaire au-dessous de vous, faisant de lui une monture aérienne. Sa Vitesse de vol est de 15 m. Il peut transporter jusqu’à 200 kg, mais sa Vitesse de vol est réduite à 9 m s’il porte plus de 100 kg. Le balai cesse son vol stationnaire quand vous posez les pieds au sol ou ne le chevauchez plus.</p><p>Au prix de l’action Magie, vous pouvez envoyer le balai voler seul vers une destination située dans un rayon de 1,5 km si vous nommez l’emplacement et connaissez cet endroit. Le balai revient à vous quand vous entreprenez l’action Magie et prononcez le mot de commande correspondant, à condition qu’il se trouve toujours dans un rayon de 1,5 km.</p>'),
  (1318, 38, 2, 1, '<p>Votre Intelligence est de 19 tant que vous portez ce bandeau. Il est sans effet sur vous si votre Intelligence est déjà supérieure ou égale à 19.</p>'),
  (1319, 38, 3, 0, '<p>Cet objet apparaît d’emblée comme une caisse oblongue en bois, longue de 30 cm pour une largeur et une hauteur de 15 cm. Elle pèse 2 kg et flotte. Il est possible de l’ouvrir et de ranger des objets à l’intérieur. L’objet est aussi doté de trois mots de commande, chacun nécessitant l’action Magie :</p><p><b>Premier mot de commande.</b> La caisse se déplie pour former une barque.</p><p><b>Deuxième mot de commande.</b> La caisse se déplie pour former une barge.</p><p><b>Troisième mot de commande.</b> Le bateau pliable se replie et retrouve sa forme de caisse si aucune créature ne se trouve à bord. Les objets restés à bord et qui ne tiennent pas dans cette caisse se retrouvent à l’extérieur de celle-ci lorsqu’elle se replie. Tout objet resté à bord du navire et qui tient dans la caisse y est rangé.</p><p>Lorsque la caisse se transforme en véhicule, son poids devient celui d’un bâtiment normal de son gabarit, et tout ce qui était rangé dans la caisse reste à bord.</p><p>Les profils de la barque et de la barge sont disponibles en section « Équipement ». Si l’un ou l’autre véhicule est réduit à 0 point de vie, le bateau pliable est détruit.</p>'),
  (1298, 37, 3, 1, '<p><em>Harmonisation requise avec un Barde, Clerc, Druide, Ensorceleur, Magicien ou Occultiste</em></p><p>Ce bâton dispose de 10 charges. Tant que vous tenez ce bâton, vous pouvez recourir à ses propriétés :</p><p><b>Incantation.</b> Vous pouvez dépenser 1 charge du bâton pour lancer charme-personne, compréhension des langues ou injonction en prenant votre DD de sauvegarde des sorts.</p><p><b>Renvoi d’enchantement.</b> Si vous réussissez un JS contre un sort d’Enchantement qui ne cible que vous, vous pouvez jouer votre Réaction pour dépenser 1 charge du bâton, ce qui renvoie le sort sur son incantateur comme si vous aviez lancé le sort.</p><p><b>Résistance aux enchantements.</b> Si vous ratez un jet de sauvegarde contre un sort d’Enchantement qui ne cible que vous, vous pouvez transformer cet échec en réussite. Cette propriété du bâton ne peut plus resservir avant l’aube suivante.</p><p><b>Récupération des charges.</b> Le bâton récupère quotidiennement 1d8 + 2 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, le bâton est réduit en poussière.</p>'),
  (1299, 37, 4, 1, '<p><em>Harmonisation requise avec un Druide, Ensorceleur, Magicien ou Occultiste</em></p><p>Vous bénéficiez de la Résistance aux dégâts de feu tant que vous tenez ce bâton.</p><p><b>Sorts.</b> Le bâton dispose de 10 charges. Lorsque vous tenez le bâton, vous pouvez lancer l’un des sorts de la table suivante en prenant votre DD de sauvegarde des sorts. La table indique le nombre de charges à dépenser pour lancer le sort.</p><p>Sort</p><p>Coût en charges Sort</p><p>Coût en charges boule de feu mur de feu mains brûlantes</p><p><b>Récupération des charges.</b> Le bâton récupère quotidiennement 1d6 + 4 charges dépensées, à l’aube.</p><p>Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, le bâton est réduit en cendres.</p>'),
  (1300, 37, 3, 1, '<p>Ce bâton dispose de 3 charges et récupère quotidiennement 1d3 charges dépensées, à l’aube.</p><p>Il peut également servir de bâton de combat magique. Une attaque qui touche avec ce bâton inflige les dégâts d’un bâton de combat normal, sachant que vous pouvez dépenser 1 charge pour qu’il inflige 2d10 dégâts nécrotiques supplémentaires à la cible et lui impose un jet de sauvegarde de Constitution DD 15. En cas d’échec, la cible subit le Désavantage pendant 1 heure à tout test de caractéristique et jet de sauvegarde basé sur la Force ou la Constitution.</p>'),
  (1301, 37, 4, 1, '<p><em>Harmonisation requise avec un Druide, Ensorceleur, Magicien ou Occultiste</em></p><p>Vous bénéficiez de la Résistance aux dégâts de froid tant que vous tenez ce bâton.</p><p><b>Sorts.</b> Le bâton dispose de 10 charges. Lorsque vous tenez le bâton, vous pouvez lancer l’un des sorts de la table suivante en prenant votre DD de sauvegarde des sorts. La table indique le nombre de charges à dépenser pour lancer le sort.</p><p>Sort cône de froid mur de glace</p><p>Coût en charges</p><p>Sort nappe de brouillard tempête de grêle</p><p>Coût en charges</p><p><b>Récupération des charges.</b> Le bâton récupère quotidiennement 1d6 + 4 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, le bâton se liquéfie et il est détruit.</p>'),
  (1302, 37, 3, 1, '<p><em>Harmonisation requise avec un Barde, Clerc ou Druide</em></p><p>Ce bâton dispose de 10 charges. Lorsque vous tenez le bâton, vous pouvez lancer l’un des sorts de la table suivante en prenant votre modificateur de caractéristique d’incantation. La table indique le nombre de charges à dépenser pour lancer le sort.</p><p>Sort restauration partielle soins soins de groupe</p><p>Coût en charges</p><p>1 charge par niveau de sort (maximum 4 pour un sort du 4e niveau)</p><p>Récupération des charges. Le bâton récupère quotidiennement 1d6 + 4 charges dépensées, à l’aube.</p><p>Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, le bâton disparaît dans un éclat de lumière, perdu à jamais.</p>'),
  (1303, 34, 4, 1, '<p>Vous recevez un bonus de +2 aux jets d’attaque et de dégâts effectués avec cette arme magique.</p><p>Tant que vous tenez cette arme, vous pouvez lui faire émettre une Lumière faible verte dans un rayon de 3 m, soit par une action Bonus, soit après avoir joué l’Initiative ; vous pouvez aussi en éteindre la lumière par une action Bonus.</p><p>Si vous tenez l’arme, vous pouvez entreprendre une action Bonus pour modifier sa forme et la transformer en bâtonnet de 15 cm (pour en faciliter le rangement) ou une perche de 3 m, ou bien la ramener à sa forme de bâton de combat. L’arme ne s’allongera que dans la limite de l’espace disponible.</p><p>Sous certaines formes, l’arme est dotée des propriétés supplémentaires suivantes.</p><p><b>Arme à distance (bâton de combat uniquement).</b> L’arme est dotée de la propriété Lancer avec une portée normale de 9 m et une portée longue de 36 m. Aussitôt après votre attaque à distance avec le bâton, il revient dans votre main.</p><p>Assistance acrobatique (bâton de combat et perche de 3 m uniquement). En tenant cette arme, vous bénéficiez de l’Avantage aux tests de Dextérité (Acrobaties).</p><p><b>Déviation d’attaque (bâton de combat uniquement).</b> Lorsque vous êtes touché par une attaque alors que vous tenez l’arme, vous pouvez jouer votre Réaction pour décrire des moulinets avec le bâton et recevoir un bonus de +5 à votre CA contre l’attaque correspondante, ce qui peut la faire échouer. Vous ne pouvez ensuite plus recourir à cette propriété avant d’avoir terminé un Repos court ou long.</p>'),
  (1304, 37, 4, 1, '<p><em>Harmonisation requise avec un Ensorceleur, Magicien ou Occultiste</em></p><p>Ce bâton, qui dispose de 20 charges, peut se manier comme un bâton de combat magique octroyant un bonus de +2 aux jets d’attaque et de dégâts. Tant que vous le tenez, vous recevez un bonus de +2 à la classe d’armure, aux jets de sauvegarde et aux jets d’attaque de sort.</p><p><b>Sorts.</b> Lorsque vous tenez le bâton, vous pouvez lancer l’un des sorts de la table suivante en prenant votre DD de sauvegarde des sorts. La table indique le nombre de charges à dépenser pour lancer le sort.</p><p>Sort boule de feu (au 5e niveau) cône de froid</p><p>Coût en charges</p><p>Sort éclair (au 5e niveau) globe d’invulnérabilité immobilisation de monstre lévitation mur de force projectile magique rayon affaiblissant</p><p>Coût en charges</p><p>5 6 5 2 5 1 1</p><p><b>Récupération des charges.</b> Le bâton récupère quotidiennement 2d8 + 4 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, le bâton conserve son bonus de +2 aux jets d’attaque et de dégâts, mais perd toutes ses autres propriétés. Sur un résultat de 20, il récupère 1d8 + 2 charges.</p><p><b>Explosion vengeresse.</b> Vous pouvez entreprendre l’action Magie pour rompre le bâton sur votre genou ou contre une surface solide. Le bâton se détruit alors en libérant sa magie dans une explosion qui emplit une Émanation de 9 m, dont il est l’origine. Vous avez 50 % de chances d’être propulsé instantanément vers un plan d’existence aléatoire et d’éviter ainsi l’explosion. Si vous n’évitez pas l’effet, vous subissez autant de dégâts de force que 16 fois le nombre de charges que contient le bâton. Chaque autre créature de la zone effectue un jet de sauvegarde de Dextérité DD 17. En cas d’échec, une créature subit autant de dégâts de force que 4 fois le nombre de charges contenues dans le bâton. En cas de réussite, elle ne subit que la moitié de ces dégâts.</p>'),
  (1305, 37, 4, 1, '<p>Ce bâton peut se manier comme un bâton de combat magique qui octroie un bonus de +2 aux jets d’attaque et de dégâts. Il dispose en outre des propriétés supplémentaires suivantes. Une fois que l’une de ces propriétés est utilisée, vous ne pouvez plus y recourir avant l’aube suivante.</p><p><b>Foudre.</b> Lorsque vous touchez une cible avec une attaque de corps à corps utilisant le bâton, vous pouvez lui infliger 2d6 dégâts de foudre supplémentaires (pas d’action requise).</p><p><b>Tonnerre.</b> Lorsque vous touchez avec une attaque de corps à corps utilisant le bâton, vous pouvez faire produire à celui-ci un éclat de tonnerre audible à 90 m (pas d’action requise). La cible que vous avez touchée doit réussir un jet de sauvegarde de Constitution DD 17 sous peine de subir l’état Étourdi jusqu’à la fin de votre tour suivant.</p><p><b>Tonnerre et foudre.</b> Aussitôt après avoir touché une cible avec une attaque de corps à corps utilisant le bâton, vous pouvez entreprendre une action Bonus pour utiliser simultanément les propriétés Foudre et Tonnerre (voir ci-dessus). Cela ne dépense pas l’utilisation quotidienne de ces deux propriétés, seulement celle de « Tonnerre et foudre ».</p><p><b>Trait de foudre.</b> Vous pouvez entreprendre l’action Magie pour faire jaillir la foudre de la pointe du bâton sur une Ligne de 1,50 m de large et 36 m de long. Chaque créature prise dans cette Ligne effectue un jet de sauvegarde de Dextérité DD 17 et subit 9d6 dégâts de foudre en cas d’échec, la moitié en cas de réussite.</p><p><b>Coup de tonnerre.</b> Vous pouvez entreprendre l’action Magie pour que le bâton produise un coup de tonnerre audible à 180 m. Chaque créature dans une Émanation de 18 m centrée sur vous effectue un jet de sauvegarde de Constitution DD 17. En cas d’échec, une créature subit 2d6 dégâts de tonnerre, ainsi que l’état Assourdi pendant 1 minute. En cas de réussite, elle subit uniquement la moitié de ces dégâts.</p>'),
  (1306, 37, 3, 1, '<p><em>Harmonisation requise avec un Druide</em></p><p>Ce bâton, qui dispose de 6 charges, peut se manier comme un bâton de combat magique octroyant un bonus de +2 aux jets d’attaque et de dégâts. Tant que vous le tenez, vous recevez un bonus de +2 aux jets d’attaque de sort.</p><p><b>Sorts.</b> Lorsque vous tenez le bâton, vous pouvez lancer l’un des sorts de la table suivante en prenant votre DD de sauvegarde des sorts. La table indique le nombre de charges à dépenser pour lancer le sort.</p><p>Sort amitié avec les animaux</p><p>Coût en charges communication avec les animaux communication avec les plantes éveil localisation d’animaux ou de plantes mur d’épines passage sans trace peau d’écorce</p><p><b>Forme d’arbre.</b> Vous pouvez entreprendre l’action Magie pour planter une extrémité du bâton dans une terre fertile en un espace inoccupé et dépenser 1 charge pour transformer le bâton en un arbre vigoureux. L’arbre mesure 18 m de haut et son tronc 1,50 m de diamètre, la ramure au sommet atteignant 6 m de rayon. L’arbre semble ordinaire, mais dégage une faible aura de magie de Transmutation détectable par le sort détection de la magie. En touchant l’arbre et en entreprenant l’action Magie, vous ramenez le bâton à sa forme normale. Toute créature perchée dans l’arbre tombe lorsque celui-ci redevient un bâton.</p><p><b>Récupération des charges.</b> Le bâton récupère quotidiennement 1d6 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, le bâton perd ses propriétés et devient un bâton de combat non magique.</p>'),
  (1307, 37, 3, 1, '<p><em>Harmonisation requise avec un Barde, Clerc, Druide, Ensorceleur, Magicien ou Occultiste</em></p><p>Ce bâton dispose de 10 charges. Nuage d’insectes. Lorsque vous tenez le bâton, vous pouvez entreprendre l’action Magie et dépenser 1 charge pour faire apparaître un essaim d’insectes volants inoffensifs dans une Émanation de 9 m centrée sur vous. Les insectes persistent pendant 10 minutes, rendant la Visibilité nulle dans la zone pour toutes les créatures autres que vous. Un vent fort (comme celui créé par bourrasque) disperse l’essaim et met fin à l’effet.</p><p><b>Sorts.</b> Lorsque vous tenez le bâton, vous pouvez lancer l’un des sorts de la table suivante en prenant votre DD de sauvegarde des sorts et votre modificateur d’attaque des sorts. La table indique le nombre de charges à dépenser pour lancer le sort.</p><p>Coût en</p><p>Sort charges fléau d’insectes insecte géant</p><p><b>Récupération des charges.</b> Le bâton récupère quotidiennement 1d6 + 4 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, une nuée d’insectes dévore le bâton et le détruit avant de se disperser.</p>'),
  (1308, 37, 2, 1, '<p>Au prix de l’action Magie, vous pouvez lancer ce bâton pour qu’il atterrisse en un espace inoccupé dans un rayon de 3 m et s’y transforme en serpent constricteur géant. Le serpent, sous votre contrôle, partage votre rang d’initiative et joue son tour juste après le vôtre.</p><p>À votre tour, vous pouvez donner un ordre mental au serpent (pas d’action requise) s’il se trouve dans un rayon de 18 m de vous et si vous ne subissez pas l’état Neutralisé. Vous décidez quelle action le serpent entreprend et où il se déplacera à son tour, ou pouvez vous contenter de lui donner une instruction plus générale, comme veiller sur un lieu ou attaquer vos ennemis. En l’absence d’ordres de votre part, le serpent se défend.</p><p>Par une action Bonus, vous pouvez ordonner au serpent de reprendre sa forme de bâton dans son espace actuel, après quoi vous ne pouvez plus utiliser la propriété du bâton pendant 1 heure. Si le serpent tombe à 0 point de vie, il meurt et retrouve sa forme de bâton ; le bâton se détruit alors en se brisant. Si le serpent retrouve sa forme de bâton avant d’avoir perdu tous ses points de vie, il les récupère tous.</p>'),
  (1309, 37, 5, 1, '<p><em>Harmonisation requise avec un Ensorceleur, Magicien ou Occultiste</em></p><p>Ce bâton, qui dispose de 50 charges, peut se manier comme un bâton de combat magique octroyant un bonus de +2 aux jets d’attaque et de dégâts. Tant que vous le tenez, vous recevez un bonus de +2 aux jets d’attaque de sort.</p><p><b>Absorption de sort.</b> Tant que vous tenez le bâton, vous avez l’Avantage aux jets de sauvegarde contre les sorts. Vous pouvez en outre jouer votre Réaction lorsqu’une autre créature lance un sort qui ne cible que vous. Dans ce cas, le bâton absorbe la magie du sort, ce qui en annule l’effet ; le bâton reçoit alors un nombre de charges égal au niveau du sort absorbé. Cependant, si cela amène le nombre total de charges du bâton au-dessus de 50, l’objet explose comme si vous aviez activé son Explosion vengeresse (voir ci-après).</p><p><b>Sorts.</b> Lorsque vous tenez le bâton, vous pouvez lancer l’un des sorts de la table suivante en prenant votre DD de sauvegarde des sorts. La table indique le nombre de charges à dépenser pour lancer le sort.</p><p>Sort</p><p>Coût en charges agrandissement/rapetissement boule de feu (au 7e niveau) changement de plan déblocage détection de la magie dissipation de la magie éclair (au 7e niveau) invisibilité invocation d’élémentaire lumière main du mage mur de feu passe-muraille protection contre le mal et le bien sphère de feu télékinésie tempête de grêle toile d’araignée verrou magique</p><p><b>Récupération des charges.</b> Le bâton récupère quotidiennement 4d6 + 2 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 20, le bâton récupère 1d12 + 1 charges.</p><p><b>Explosion vengeresse.</b> Vous pouvez entreprendre l’action Magie pour rompre le bâton sur votre genou ou contre une surface solide. Le bâton se détruit alors en libérant sa magie dans une explosion qui emplit une Émanation de 9 m, dont il est l’origine. Vous avez</p><p>50 % de chances d’être propulsé instantanément vers un plan d’existence aléatoire et d’éviter ainsi l’explosion. Si vous n’évitez pas l’effet, vous subissez autant de dégâts de force que 16 fois le nombre de charges que contient le bâton. Chaque autre créature de la zone effectue un jet de sauvegarde de Dextérité DD 17. En cas d’échec, une créature subit des dégâts de force égaux à 6 fois le nombre de charges contenues dans le bâton. En cas de réussite, elle ne subit que la moitié de ces dégâts.</p>'),
  (1310, 37, 4, 1, '<p>Ce bâton peut se manier comme un bâton de combat magique qui octroie un bonus de +3 aux jets d’attaque et de dégâts.</p><p>Le bâton dispose de 10 charges. Lorsque vous touchez avec une attaque de corps à corps par son intermédiaire, vous pouvez dépenser jusqu’à 3 charges. Pour chaque charge dépensée, la cible subit 1d6 dégâts de force supplémentaires.</p><p>Récupération des charges. Le bâton récupère quotidiennement 1d6 + 4 charges dépensées, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, le bâton devient un bâton de combat non magique.</p>'),
  (1320, 38, 2, 1, '<p>Ces bottes disposent de 4 charges et récupèrent quotidiennement 1d4 charges dépensées, à l’aube. Tant qu’elles vous chaussent, vous pouvez entreprendre l’action Magie pour dépenser 1 charge et recevoir une Vitesse de vol de 9 m pendant 1 heure. Si vous volez au moment où la durée expire, vous descendez à une vitesse de 9 m par round jusqu’à ce que vous touchiez terre.</p>'),
  (1321, 38, 3, 1, '<p>Porter ces bottes vous permet de lancer le sort lévitation sur vous-même.</p>'),
  (1322, 38, 3, 1, '<p>Tant que vous portez ces bottes, vous pouvez consacrer une action Bonus à faire claquer vos talons l’un contre l’autre. Dès lors, les bottes doublent votre Vitesse et toute créature qui effectue une attaque d’Opportunité contre vous subit le Désavantage à son jet d’attaque. Cet effet prend fin si vous faites de nouveau claquer vos talons.</p><p>Quand la propriété des bottes a été utilisée pendant un total de 10 minutes, leur magie cesse de fonctionner jusqu’à ce que vous ayez terminé un Repos long.</p>'),
  (1323, 38, 2, 1, '<p>Tant que vous portez ces bottes, votre Vitesse devient 9 m sauf si elle est déjà supérieure, et elle n’est pas réduite par le fait de porter un poids supérieur à votre capacité de charge ni une armure lourde.</p><p>Une fois à chacun de vos tours, vous pouvez effectuer un saut de 9 m maximum en ne dépensant que 3 m de déplacement.</p>'),
  (1324, 38, 2, 1, '<p>Ces confortables bottes fourrées gardent les pieds au chaud. Tant que vous les portez, vous recevez les bénéfices suivants :</p><p><b>Arpenteur de l’hiver.</b> Vous ne tenez pas compte du Terrain difficile créé par la glace et la neige.</p><p><b>Résistance au froid.</b> Vous bénéficiez de la Résistance aux dégâts de froid et tolérez les températures inférieures à –18 °C sans protection supplémentaire.</p>'),
  (1325, 38, 2, 0, '<p>Tant que vous portez ces bottes, vos pas restent silencieux, quelle que soit la surface que vous foulez. Vous avez l’Avantage aux tests de Dextérité (Discrétion).</p>'),
  (1275, 35, 4, 1, '<p>Tant que vous maniez ce bouclier, vous pouvez l’animer par une action Bonus. Le bouclier s’élance dans les airs, reste en vol stationnaire dans votre espace en vous protégeant comme si vous le portiez, ce qui vous laisse les mains libres. Le bouclier reste animé pendant 1 minute, mais disparaît avant cela si vous consacrez une action Bonus pour mettre fin à cet effet, mourez ou subissez l’état Neutralisé ; il tombe alors au sol ou revient dans votre main si vous avez une main libre.</p>'),
  (1276, 35, 3, 1, '<p>Vous recevez un bonus de +2 à la classe d’armure contre les jets d’attaque à distance tant que vous portez ce bouclier. Ce bonus s’ajoute à celui que le bouclier octroie normalement à la CA.</p><p>Chaque fois qu’un assaillant effectue un jet d’attaque à distance contre une cible dans un rayon de 1,50 m de vous, vous pouvez jouer votre Réaction pour devenir la cible de cette attaque à sa place.</p>'),
  (1277, 35, 3, 1, '<p>Tant que vous tenez ce bouclier, vous bénéficiez de la Résistance aux dégâts des attaques des armes à distance.</p><p>Malédiction. Ce bouclier est maudit. S’harmoniser avec lui vous maudit jusqu’à ce que vous soyez la cible du sort délivrance des malédictions ou d’un effet magique équivalent. Retirer le bouclier ne suffit pas à lever la malédiction. Chaque fois qu’une attaque avec une arme à distance cible une créature dans un rayon de 3 m de vous, vous en devenez en fait la cible.</p>'),
  (1278, 35, 4, 1, '<p>Tant que vous portez ce bouclier, vous recevez un bonus de +2 à la classe d’armure. Ce bonus s’ajoute à celui que le bouclier octroie normalement à la CA.</p><p>Le bouclier dispose des propriétés supplémentaires suivantes, accessibles lorsque vous le tenez.</p><p><b>Champ protecteur.</b> Lorsque vous-même ou un allié que vous voyez dans un rayon de 1,50 m êtes la cible d’une attaque ou effectuez un jet de sauvegarde contre une zone d’effet, vous pouvez jouer votre Réaction pour que le bouclier produise une Émanation immobile de 1,50 m centrée sur vous. Quand apparaît l’Émanation, tous les objets et créatures qui n’y sont que partiellement sont repoussés vers les espaces inoccupés les plus proches, hors de l’Émanation. L’attaque ou la zone d’effet qui a déclenché la Réaction reste sans effet sur les créatures et objets dans l’Émanation, qui persiste tant que vous maintenez votre Concentration (maximum 1 minute). Rien ne peut entrer dans l’Émanation ni en sortir. Les créatures et objets dans l’Émanation ne peuvent subir de dégâts des attaques et effets venant de l’autre côté, pas plus qu’une créature à l’intérieur ne peut infliger de dégâts vers l’extérieur. Une fois cette propriété utilisée, vous ne pouvez plus y recourir avant l’aube suivante.</p><p><b>Taquet.</b> Lorsque vous entreprenez l’action Attaque, vous pouvez effectuer l’un des jets d’attaque avec le bouclier, contre une cible dans un rayon de 1,50 m. Appliquez votre bonus de maîtrise et votre modificateur de Force à ce jet d’attaque. Si l’attaque touche, le bouclier inflige à la cible des dégâts de force égaux à 2d6 + 2 plus votre modificateur de Force. Si la cible est une créature, vous pouvez en outre la repousser d’un maximum de 3 m. Si sa catégorie de taille est inférieure ou égale à la vôtre, vous pouvez aussi lui imposer l’état À terre.</p>'),
  (1279, 35, 4, 1, '<p>Tant que vous tenez ce bouclier, vous avez l’Avantage aux jets de sauvegarde contre les sorts et autres effets magiques, et les jets d’attaque de sort contre vous subissent le Désavantage.</p>'),
  (1280, 35, 2, 0, '<p>Tant que vous tenez ce bouclier, vous bénéficiez de l’Avantage aux jets d’Initiative et aux tests de Sagesse (Perception). Ce bouclier est orné d’un symbole représentant un œil.</p>'),
  (1326, 38, 4, 1, '<p>Tant que vous touchez cet orbe de cristal, vous pouvez lancer scrutation (DD de sauvegarde 17) par son biais.</p>'),
  (1327, 38, 5, 1, '<p>Tant que vous touchez cet orbe de cristal, vous pouvez lancer scrutation (DD de sauvegarde 17) par son biais. Vous pouvez en outre lancer détection des pensées (DD de sauvegarde 17) en prenant pour cible les créatures que vous voyez dans un rayon de 9 m du capteur du sort. Vous n’avez pas besoin de vous concentrer sur le sort détection des pensées pour le maintenir pendant toute sa durée, mais il s’achève si le sort scrutation se termine.</p>'),
  (1328, 38, 5, 1, '<p>Tant que vous touchez cet orbe de cristal, vous pouvez lancer scrutation (DD de sauvegarde 17) par son biais. Vous pouvez en outre communiquer par télépathie avec les créatures que vous voyez dans un rayon de 9 m du capteur du sort. Vous pouvez enfin lancer suggestion (DD de sauvegarde 17) par le biais du capteur sur l’une de ces créatures. Vous n’avez pas besoin de vous concentrer sur cette suggestion pour la maintenir pendant toute sa durée, mais elle s’achève si la scrutation se termine. Vous ne pouvez pas relancer suggestion par ce biais avant l’aube suivante.</p>'),
  (1329, 38, 5, 1, '<p>Tant que vous touchez cet orbe de cristal, vous pouvez lancer scrutation (DD de sauvegarde 17) par son biais. Vous bénéficiez en outre de la Vision lucide à 36 m, centrée sur le capteur du sort.</p>'),
  (1330, 38, 4, 0, NULL),
  (1331, 38, 2, 1, '<p>Tant que vous portez ces bracelets, vous avez la maîtrise de l’arc long et de l’arc court, et recevez un bonus de +2 aux jets de dégâts effectués avec ces armes.</p>'),
  (1332, 38, 3, 1, '<p>Tant que vous portez ces bracelets et ne portez ni armure ni bouclier, vous recevez un bonus de +2 à la CA.</p>'),
  (1333, 38, 3, 0, '<p>Tant que ce brasero se trouve dans un rayon de 1,50 m de vous, vous pouvez entreprendre l’action Magie pour convoquer un élémentaire du feu. L’élémentaire apparaît en un espace inoccupé aussi près que possible du brasero, comprend les mêmes langues que vous, obéit à vos ordres et joue son tour juste après vous à votre rang d’initiative. Il disparaît au bout de 1 heure, s’il meurt, ou si vous le révoquez par une action Bonus. Le brasero ne peut plus être utilisé de cette manière avant l’aube suivante.</p>'),
  (1334, 38, 2, 1, '<p>Tant que vous portez cette broche, vous bénéficiez de la Résistance aux dégâts de force et de l’Immunité contre les dégâts du sort projectile magique.</p>'),
  (1335, 38, 5, 1, '<p>Cette cape dispose de 3 charges et récupère quotidiennement 1d3 charges dépensées, à l’aube. Tant que vous portez cette cape, vous pouvez entreprendre l’action Magie pour vous couvrir la tête de sa capuche et dépenser 1 charge, ce qui vous octroie l’état Invisible pendant 1 heure. L’effet prend fin prématurément si vous vous décoiffez de la capuche (pas d’action requise) ou cessez de porter la cape.</p>'),
  (1336, 38, 3, 1, '<p>Tant que vous portez cette cape, elle projette magiquement un double illusoire de vous-même qui vous fait apparaître à côté de votre véritable position. Toutes les créatures subissent le Désavantage à leurs jets d’attaque contre vous. Si vous subissez des dégâts, cette propriété cesse de fonctionner jusqu’au début de votre tour suivant. Cette propriété est réprimée quand votre Vitesse tombe à 0 et tant qu’elle le reste.</p>'),
  (1337, 38, 4, 1, '<p>Ce somptueux vêtement en soie noire est brodé de fils d’argent. Tant que vous le portez, vous recevez les bénéfices suivants :</p><p><b>Déplacement arachnéen.</b> Aucune toile d’araignée ne peut vous coincer ; vous pouvez vous déplacer librement à travers toute toile d’araignée comme s’il s’agissait d’un Terrain difficile.</p><p><b>Pattes d’araignée.</b> Vous bénéficiez d’une Vitesse d’escalade égale à votre Vitesse et pouvez monter, descendre ou vous déplacer à l’horizontale sur une surface verticale ou encore au plafond, la tête en bas, tout en gardant les mains libres.</p><p><b>Résistance au poison.</b> Vous bénéficiez de la Résistance aux dégâts de poison.</p><p><b>Toile d’araignée.</b> Vous pouvez lancer toile d’araignée (DD de sauvegarde 13). La toile d’araignée créée par ce sort remplit le double de la surface normale. Une fois utilisée, cette propriété ne peut plus resservir avant l’aube suivante.</p>'),
  (1338, 38, 3, 1, '<p>Tant que vous portez cette cape, vous bénéficiez de l’Avantage aux tests de Dextérité (Discrétion). Dans une zone de Lumière faible ou de Ténèbres, vous pouvez saisir les bords de la cape à deux mains et l’utiliser pour recevoir une Vitesse de vol de 12 m. Si vous lâchez les bords de la cape en volant de cette manière, ou si vous n’êtes plus dans une zone de Lumière faible ou de Ténèbres, vous perdez cette Vitesse de vol.</p><p>Tant que vous portez cette cape dans une zone de Lumière faible ou de ténèbres, vous pouvez lancer métamorphose sur vous-même, qui vous transforme en chauve-souris. Sous cette forme, vous conservez vos valeurs d’Intelligence, de Sagesse et de Charisme. La cape ne peut plus être utilisée de cette manière jusqu’à l’aube suivante.</p>'),
  (1339, 38, 2, 1, '<p>Tant que vous portez cette cape, vous pouvez respirer sous l’eau et disposez d’une Vitesse de nage de 18 m.</p>'),
  (1340, 38, 2, 1, '<p>Vous recevez un bonus de +1 à la classe d’armure et aux jets de sauvegarde tant que vous portez cette cape.</p>'),
  (1341, 38, 3, 1, '<p>Tant que vous portez cette cape, vous pouvez entreprendre l’action Magie pour la transformer en paire d’ailes dans votre dos. Elles persistent pendant 1 heure, sauf si vous y mettez fin prématurément au prix de l’action Magie. Ces ailes vous octroient une Vitesse de vol de 18 m. Si vous êtes en l’air lorsqu’elles disparaissent, vous tombez. Après leur disparition, vous ne pouvez plus les déployer pendant 1d12 heures.</p>'),
  (1342, 38, 3, 0, '<p>Cette cape sent légèrement le soufre. Quand vous la portez, vous pouvez l’utiliser pour lancer porte dimensionnelle au prix de l’action Magie. Cette propriété ne peut plus resservir avant l’aube suivante.</p><p>En vous téléportant avec ce sort, vous laissez derrière vous un nuage de fumée. Cette fumée entraîne une Visibilité réduite dans l’espace que vous venez de quitter jusqu’à la fin de votre tour suivant.</p>'),
  (1343, 38, 2, 1, '<p>Tant que vous portez cette cape, tout test de Sagesse (Perception) effectué pour vous repérer subit le Désavantage, et vous bénéficiez de l’Avantage à vos tests de Dextérité (Discrétion).</p>'),
  (1344, 38, 2, 0, '<p>Ce récipient muni d’un bouchon clapote quand on l’agite, comme s’il contenait de l’eau. La carafe pèse 1 kg.</p><p>Vous pouvez consacrer l’action Magie à retirer le bouchon et prononcer l’un des trois mots de commande, après quoi une quantité d’eau douce ou d’eau salée (au choix) s’écoule de la carafe. L’eau cesse de couler au début de votre tour suivant. Choisissez parmi les mots de commande suivants :</p><p>Éclaboussure. La carafe produit 4 litres d’eau. Fontaine. La carafe produit 20 litres d’eau. Geyser. La carafe produit 120 litres d’une eau qui jaillit sous la forme d’une Ligne de 9 m de long pour 30 cm de large. En tenant la carafe, vous pouvez orienter le geyser dans une direction (pas d’action requise). Une créature de votre choix présente sur cette Ligne doit réussir un jet de sauvegarde de Force DD 13 sous peine de subir 1d4 dégâts contondants et l’état À terre. Au lieu d’une créature, vous pouvez prendre pour cible un objet sur la Ligne qui n’est porté par personne et dont le poids n’excède pas 100 kg. L’objet est renversé par le geyser.</p>'),
  (1345, 38, 3, 0, '<p>Ce tube de métal creux, long d’environ 30 cm, pèse 500 g. Au prix de l’action Magie, vous pouvez tinter le carillon pour lancer déblocage. Le son habituel du sort est remplacé par le tintement clair du carillon, audible à 90 m.</p><p>Le carillon peut être utilisé 10 fois. Il se fissure et devient inutilisable après la dixième utilisation.</p>'),
  (1346, 38, 2, 0, '<p>Chacun des trois compartiments de ce carquois est lié à un espace extradimensionnel qui permet au carquois de contenir de nombreux objets sans jamais peser plus de 1 kg. Le compartiment court peut contenir jusqu’à 60 flèches, carreaux ou objets comparables. Le compartiment de taille intermédiaire peut contenir jusqu’à 18 javelines ou objets comparables. Le compartiment long peut contenir jusqu’à 6 objets longs de type arc, bâton de combat ou lance.</p><p>Vous pouvez extraire n’importe quel objet contenu dans le carquois comme si vous le tiriez d’un carquois ou d’un fourreau ordinaire.</p>'),
  (1353, 38, 3, 1, '<p>Tant que vous portez ce ceinturon, vous recevez les bénéfices suivants :</p><p><b>Ami des nains.</b> Vous bénéficiez de l’Avantage aux tests de Charisme (Persuasion) effectués dans le cadre d’interactions avec des nains et des duergars.</p><p><b>Nain.</b> Vous parlez et lisez le nain. Robustesse. Votre Constitution augmente de 2, jusqu’à un maximum de 20.</p><p>En outre et tant que vous êtes harmonisé avec le ceinturon, il y a chaque jour à l’aube 50 % de chances qu’une barbe fournie vous couvre le menton si votre physiologie vous le permet, ou que votre barbe épaississe si vous en arboriez déjà une.</p><p>Si vous n’êtes ni nain ni duergar, vous recevez les bénéfices suivants tant que vous portez ce ceinturon :</p><p><b>Résilience.</b> Vous bénéficiez de la Résistance aux dégâts de poison. Vous avez en outre l’Avantage aux jets de sauvegarde visant à éviter l’état Empoisonné ou à y mettre un terme sur vous-même.</p><p><b>Vision dans le noir.</b> Vous disposez de la Vision dans le noir sur 18 m.</p>'),
  (1354, 38, 2, 1, '<p>Tant que vous portez ce chapeau sur la tête, vous pouvez lancer le sort déguisement. Le sort prend fin si vous ne coiffez plus le chapeau.</p>'),
  (1355, 38, 4, 1, NULL),
  (1356, 38, 3, 1, NULL),
  (1357, 38, 2, 1, '<p>Tant que vous portez ces chaussures légères, vous pouvez vous déplacer dans toutes les directions le long des surfaces verticales, ainsi que sur les plafonds, tout en gardant les mains libres. Vous bénéficiez d’une Vitesse d’escalade égale à votre Vitesse. Toutefois, ces chaussons ne facilitent en rien les déplacements sur une surface glissante, couverte d’huile ou de glace par exemple.</p>'),
  (1358, 38, 4, 1, NULL),
  (1221, 34, 4, 1, '<p>Vous recevez un bonus de +2 aux jets d’attaque et de dégâts effectués avec cette arme magique. Vous pouvez en outre effectuer une attaque avec ce cimeterre par une action Bonus à chacun de vous tours.</p>'),
  (1359, 38, 5, 0, '<p>Cette substance visqueuse d’un blanc laiteux permet de créer un lien adhésif permanent entre deux objets. Cette colle doit être stockée dans un pot ou une flasque dont on a préalablement enduit l’intérieur d’huile d’insaisissabilité. Lorsqu’on le découvre, un tel récipient contient 1d6 + 1 doses de 30 grammes.</p><p>Une dose de colle suffit à couvrir une surface carrée de 30 cm de côté. L’application d’une dose de colle universelle requiert l’action Utilisation, sachant que la colle met 1 minute à sécher. Après cela, le lien qu’elle crée ne peut être défait que par l’application de solvant universel, d’huile éthérée ou par le sort souhait.</p>'),
  (1360, 38, 2, 1, '<p>Tant que vous portez ce collier, vous pouvez respirer normalement dans n’importe quel environnement et bénéficiez de l’Avantage aux jets de sauvegarde visant à éviter l’état Empoisonné ou à y mettre fin.</p>'),
  (1361, 38, 3, 0, '<p>1d6 + 3 perles sont enfilées sur le collier. Vous pouvez entreprendre l’action Magie pour détacher une perle et la lancer jusqu’à 18 m. Quand la perle arrive en fin de trajectoire, elle détone en produisant l’équivalent du sort du 3e niveau boule de feu (DD de sauvegarde 15).</p><p>Vous pouvez lancer plusieurs perles, voire le collier entier, en une seule fois. Dans ce cas, augmentez les dégâts de la boule de feu de 1d6 pour chaque perle en plus de la première (maximum 12d6).</p>'),
  (1362, 38, 3, 0, '<p>Vous pouvez entreprendre l’action Magie pour souffler dans ce cor, qui émet dans un Cône de 9 m un son tonitruant audible à 180 m. Chaque créature prise dans le Cône effectue un jet de sauvegarde de Constitution DD 15. En cas d’échec, une créature subit 5d8 dégâts de tonnerre, ainsi que l’état Assourdi pendant 1 minute. En cas de réussite, elle subit uniquement la moitié de ces dégâts. Les objets en verre ou en cristal présents dans le Cône et n’étant portés par personne subissent 10d8 dégâts de tonnerre.</p><p>Chaque utilisation de la magie du cor a 20 % de chances d’en provoquer l’explosion. L’explosion inflige 10d6 dégâts de force à l’utilisateur et détruit le cor.</p>'),
  (1367, 38, 2, 0, '<p>Cette corde de 18 m de long peut supporter jusqu’à 1 500 kg. En tenant une extrémité de la corde, vous pouvez entreprendre l’action Magie pour ordonner à l’autre extrémité de s’animer et de se déplacer vers la destination de votre choix, dans les limites de la longueur de la corde. L’extrémité animée se déplace de 3 m à votre tour la première fois que vous lui en donnez l’ordre et de 3 m supplémentaires au début de chacun de vos tours suivants jusqu’à avoir atteint sa destination ou que vous lui ordonniez de s’arrêter. Vous pouvez en outre ordonner à la corde de se nouer solidement à un objet ou de se détacher, de passer de corde lisse à corde à nœuds et inversement ou de s’enrouler pour le transport.</p><p>Si vous optez pour une corde à nœuds, des nœuds épais apparaissent tous les 30 cm environ sur toute sa longueur. Sous sa forme à nœuds, la corde ne mesure plus que 15 m de long et octroie l’Avantage aux tests de caractéristique effectués pour grimper.</p><p>Elle présente le profil suivant : CA 20, 20 pv, Immunité contre les dégâts psychiques et de poison. Tant qu’il lui reste au moins 1 point de vie, elle récupère 1 pv toutes les 5 minutes. Une corde qui tombe à 0 pv est détruite.</p>'),
  (1368, 38, 3, 0, '<p>Cette corde est longue de 9 m. En tenant une extrémité de la corde, vous pouvez entreprendre l’action Magie pour ordonner à l’autre extrémité de se projeter en avant afin d’enchevêtrer une créature que vous voyez dans un rayon de 6 m. La cible doit réussir un jet de sauvegarde de Dextérité DD 15 sous peine de subir l’état Entravé. Vous pouvez libérer la cible en lâchant votre extrémité de la corde (qui se love alors spontanément dans l’espace de la cible) ou en répétant l’ordre par une action Bonus (la corde s’enroule alors dans votre main).</p><p>Une cible Entravée par la corde peut consacrer une action à effectuer, au choix, un test de Force (Athlétisme) ou de Dextérité (Acrobaties) DD 15. En cas de réussite, elle n’est plus Entravée par la corde. Si vous tenez toujours la corde lorsqu’une cible s’en échappe, vous pouvez jouer votre Réaction pour ordonner à la corde de s’enrouler dans votre main ; sans cela, elle se love dans l’espace de la cible.</p><p>Elle présente le profil suivant : CA 20, 20 pv, Immunité contre les dégâts psychiques et de poison. Tant qu’il lui reste au moins 1 point de vie, elle récupère 1 pv toutes les 5 minutes. Une corde qui tombe à 0 pv est détruite.</p>'),
  (1369, 38, 3, 1, '<p>Ce cube mesure 2 à 3 centimètres d’arête. Chaque face s’orne d’un symbole distinct. Il vous suffit d’appuyer sur une face et de dépenser le nombre de charges requis pour lancer le sort associé à cette face (DD de sauvegarde 17), comme indiqué sur la table « Faces du cube de force ».</p><p>Le cube dispose de 10 charges et récupère quotidiennement 1d6 charges dépensées, à l’aube.</p><p>Faces du cube de force</p><p>Sort armure du mage bouclier petite hutte sanctuaire privé sphère résiliente mur de force</p><p>Coût en charges 1 1 3 4 4 5</p>'),
  (1370, 38, 5, 0, '<p>Ce cube mesure 7,5 cm d’arête et diffuse une énergie magique palpable. Les six faces du cube sont chacune liées à un plan d’existence distinct, l’un d’eux étant le Plan Matériel. Les autres faces sont liées à des plans déterminés par le MJ.</p><p>Le cube dispose de 3 charges et récupère quotidiennement 1d3 charges dépensées, à l’aube. Au prix de l’action Magie, vous pouvez dépenser 1 charge du cube pour lancer l’un des sorts ci-après par le biais du cube.</p><p><b>Changement de plan.</b> Appuyer deux fois sur une face du cube vous permet de lancer changement de plan, qui transporte les cibles sur le plan d’existence lié à cette face.</p><p><b>Portail.</b> Appuyer sur une face du cube vous permet de lancer portail, qui ouvre un portail vers le plan d’existence lié à cette face.</p>'),
  (1222, 34, 3, 0, '<p>Vous recevez un bonus de +1 aux jets d’attaque et de dégâts effectués avec cette arme magique.</p><p>Par une action Bonus, vous enduisez magiquement la lame de poison. Le poison persiste 1 minute ou jusqu’à ce qu’une attaque avec cette arme touche une créature. Cette créature doit réussir un jet de sauvegarde de Constitution DD 15 sous peine de subir 2d10 dégâts de poison et l’état Empoisonné pendant 1 minute. L’arme ne peut plus resservir de cette manière avant l’aube suivante.</p>'),
  (1371, 38, 2, 0, '<p>Tant que vous portez ce diadème, vous pouvez lancer rayon ardent par son biais (+5 pour toucher). Le diadème ne peut alors plus relancer ce sort avant l’aube suivante.</p>'),
  (1372, 40, 4, 0, '<p>Lorsque vous buvez cet élixir, votre âge physique diminue de 1d6 + 6 ans, jusqu’à un minimum de 13 ans. Chaque fois que vous ingérez un élixir de jouvence au-delà du premier, il y a 10 % de chances cumulatives que vous vieillissiez au contraire de 1d6 + 6 ans.</p><p>Un minuscule cœur en suspension dans ce liquide ambré bat encore, contre toute logique. Ces ingrédients disparaissent à l’ouverture de la potion.</p>'),
  (1373, 40, 3, 0, '<p>Boire cette potion vous guérit de toute contagion magique. Les états ci-après prennent en outre fin pour vous : Assourdi, Aveuglé, Empoisonné et Paralysé.</p><p>Ce liquide rouge limpide est constellé de petites bulles de lumière.</p>'),
  (1374, 38, 3, 0, '<p>Entreprendre l’action Magie tout en faisant osciller cet encensoir vous permet de convoquer un élémentaire de l’air. L’élémentaire apparaît en un espace inoccupé aussi près que possible de l’encensoir, comprend les mêmes langues que vous, obéit à vos ordres et joue son tour juste après vous à votre rang d’initiative. Il disparaît au bout de 1 heure ; plus tôt s’il meurt ou si vous le révoquez par une action Bonus. L’encensoir ne peut plus être utilisé de cette manière avant l’aube suivante.</p>'),
  (1223, 34, 4, 1, '<p>Lorsque vous attaquez un objet avec cette arme magique et que l’attaque touche, vos dés de dégâts d’arme contre cette cible sont maximisés.</p><p>Lorsque vous attaquez une créature avec cette arme et obtenez un 20 sur le d20 du jet d’attaque, cette cible subit 14 dégâts tranchants supplémentaires et reçoit 1 niveau d’Épuisement.</p>'),
  (1224, 34, 4, 1, '<p>Par une action Bonus, vous lancez cette arme magique en l’air. Ce faisant, l’arme prend son envol avec le vol stationnaire et s’élance sur une distance maximale de 9 m en attaquant la créature de votre choix dans un rayon de 1,50 m d’elle. L’arme utilise votre jet d’attaque et ajoute votre modificateur de caractéristique aux jets de dégâts.</p><p>Tant que l’épée est en vol stationnaire, vous pouvez par une action Bonus la faire voler sur une distance maximale de 9 m vers un autre endroit situé dans un rayon de 9 m de vous. Dans le cadre de la même action Bonus, vous pouvez ordonner à l’arme d’attaquer une créature dans un rayon de 1,50 m d’elle.</p><p>Après avoir attaqué ainsi une quatrième fois, l’arme file jusqu’à vous en tentant de revenir dans votre main. Si vous n’avez aucune main libre, l’arme tombe au sol dans votre espace. En l’absence de chemin dégagé jusqu’à vous, l’arme se rapproche au maximum puis tombe au sol. Elle cesse également son vol stationnaire si vous l’empoignez ou vous retrouvez à plus de 9 m d’elle.</p>'),
  (1225, 34, 3, 1, '<p>Lorsque vous touchez une créature avec une attaque utilisant cette arme magique, la cible subit 2d6 dégâts nécrotiques supplémentaires et doit réussir un jet de sauvegarde de Constitution DD 15 sous peine de ne plus pouvoir récupérer de points de vie pendant 1 heure. La cible réitère le JS à la fin de chacun de ses tours et met un terme à l’effet sur elle-même en cas de réussite.</p>'),
  (1226, 34, 3, 1, '<p>Cet objet se présente comme une simple poignée d’épée. Lame de radiance. Quand vous la tenez en main, vous pouvez en faire surgir une lame de lumière pure ou faire disparaître celle-ci, par une action Bonus. Tant que la lame existe, cette arme magique fonctionne comme une épée longue dotée de la propriété Finesse. Si vous avez la maîtrise des épées courtes ou des épées longues, vous avez aussi celle de cette épée radieuse.</p><p>Vous recevez un bonus de +2 aux jets d’attaque et de dégâts effectués avec cette arme, qui inflige des dégâts radiants au lieu de dégâts tranchants. Quand vous touchez un Mort-vivant avec cette arme, la cible subit 1d8 dégâts radiants supplémentaires.</p><p>Lumière du soleil. La lame lumineuse de l’épée émet une Lumière vive sur un rayon de 4,50 m et une Lumière faible sur 4,50 m de plus. Cette lumière est celle du soleil. Tant que la lame persiste, vous pouvez entreprendre l’action Magie pour étendre ou réduire ses rayons de Lumière vive et de Lumière faible de 1,50 m chacun, jusqu’à un maximum de 9 m chacun ou un minimum de 3 m chacun.</p>'),
  (1227, 34, 3, 1, '<p>Lorsque vous attaquez une créature avec cette arme magique et obtenez un 20 sur le d20 du jet d’attaque, la cible subit 15 dégâts nécrotiques supplémentaires si elle n’est ni un Artificiel ni un Mort-vivant, et vous recevez autant de points de vie temporaires que les dégâts nécrotiques infligés.</p>'),
  (1228, 34, 5, 1, '<p>Vous recevez un bonus de +3 aux jets d’attaque et de dégâts effectués avec cette arme magique.</p><p>De plus, l’arme passe outre à la Résistance aux dégâts tranchants.</p><p>Lorsque vous utilisez cette arme pour attaquer une créature dotée d’au moins une tête et que vous obtenez un 20 sur le d20 du jet d’attaque, vous tranchez l’une de ces têtes. La créature meurt si elle ne peut survivre sans cette tête. Une créature est immunisée contre cet effet si elle a l’Immunité contre les dégâts tranchants, n’a pas de tête ou peut s’en passer, ou encore si le MJ estime qu’elle est trop imposante pour que l’arme puisse lui trancher la tête. Une telle créature subit en fait 30 dégâts tranchants supplémentaires sur un tel coup. Si la créature dispose d’une Résistance légendaire, elle peut en dépenser une utilisation quotidienne pour éviter la décapitation, et subit uniquement les dégâts supplémentaires.</p>'),
  (1375, 38, 2, 0, '<p>Lorsque vous tenez cet éventail, vous pouvez lancer bourrasque (DD de sauvegarde 13) par son biais. Cependant, chaque nouvelle utilisation avant l’aube suivante fragilise l’objet : les risques qu’il se désagrège augmentent de 20 % à chaque fois. Si cela se produit, il est réduit à l’état de lambeaux non magiques inutilisables.</p>'),
  (1229, 34, 4, 1, '<p>Lorsque votre jet d’attaque touche avec cette arme magique, la cible subit 1d6 dégâts de froid supplémentaires. En outre et tant que vous tenez l’arme, vous bénéficiez de la Résistance aux dégâts de feu.</p><p>Lorsqu’il gèle, l’arme émet une Lumière vive sur un rayon de 3 m et une Lumière faible sur 3 m de plus.</p><p>En dégainant cette arme, vous pouvez décider d’éteindre toutes les flammes non magiques dans un rayon de 9 m. Une fois utilisée, cette propriété ne peut plus resservir pendant 1 heure.</p>'),
  (1230, 38, 3, 0, '<p>Ces fers à cheval vont par quatre. Au prix de l’action Magie, vous pouvez mettre l’un des fers au contact du sabot d’un cheval ou d’une créature équivalente : le fer se fixe au sabot. Retirer un fer nécessite également l’action Magie.</p><p>Si les quatre fers sont fixés aux sabots de la même créature, la Vitesse de celle-ci augmente de 9 m.</p>'),
  (1231, 38, 4, 0, '<p>Ces fers à cheval vont par quatre. Au prix de l’action Magie, vous pouvez mettre l’un des fers au contact du sabot d’un cheval ou d’une créature équivalente : le fer se fixe au sabot. Retirer un fer nécessite également l’action Magie.</p><p>Si les quatre fers sont fixés aux sabots d’un cheval ou d’une créature équivalente, ils permettent à cette créature de se déplacer normalement tout en flottant 10 cm au-dessus du sol. Cet effet signifie que la créature peut traverser ou survoler des surfaces non solides ou instables, comme l’eau ou la lave. La créature ferrée ne laisse aucune trace et n’est pas soumise au Terrain difficile. Elle peut en outre voyager pendant 12 heures par jour sans recevoir de niveau d’Épuisement.</p>'),
  (1387, 38, 5, 0, '<p>Lorsque vous tenez cette flasque de fer au bouchon de laiton, vous pouvez entreprendre l’action Magie pour cibler une créature que vous voyez dans un rayon de 18 m. Si la flasque est vide et que cette cible est originaire d’un plan d’existence autre que celui sur lequel vous vous trouvez, elle doit réussir un jet de sauvegarde de Sagesse DD 17 sous peine d’être emprisonnée dans la flasque. Une cible qui a déjà été séquestrée dans la flasque a l’Avantage à ce JS. Une fois emprisonnée, une créature reste confinée dans la flasque jusqu’à ce qu’elle en soit libérée. La flasque ne peut détenir qu’une créature à la fois. Une créature piégée dans la flasque ne vieillit pas et n’a pas besoin de respirer, manger ou boire.</p><p>Vous pouvez entreprendre l’action Magie pour retirer le bouchon de la flasque et libérer la créature qu’elle contient. La créature obéit alors à vos ordres pendant 1 heure ; elle les comprend même si elle ne connaît pas la langue dans laquelle ils sont formulés. Si vous ne donnez aucun ordre ou si vous lui intimez une activité susceptible d’entraîner sa mort ou son emprisonnement, la créature se défend mais ne prend aucune autre initiative. À la fin de cette durée, la créature se comporte à nouveau en accord avec sa personnalité et son alignement.</p><p>Le sort identification révèle si la flasque contient une créature, mais seule l’ouverture du récipient permet d’en déterminer la nature exacte. Une flasque de fer qui vient d’être découverte peut déjà contenir une créature choisie par le MJ.</p>'),
  (1388, 38, 2, 1, '<p>Tant que cette flûte est sur vous, les rats ordinaires et les rats géants vous sont Indifférents et ne vous attaqueront pas, sauf si vous les menacez ou leur faites du mal.</p><p>Cette flûte dispose de 3 charges et récupère quotidiennement 1d3 charges dépensées, à l’aube. Si vous en jouez au prix de l’action Magie, vous pouvez dépenser 1 à 3 charges par une action Bonus, appelant à vous une nuée de rats pour chaque charge dépensée, à condition qu’il y ait suffisamment de rats dans un rayon de 750 m susceptibles de répondre à cet appel (cette décision appartient au MJ). S’il n’y a pas assez de rats dans les environs pour former une nuée, la charge est perdue. Les nuées appelées se déplacent vers l’origine de la mélodie par le chemin le plus sûr, mais elles ne sont pas sous votre contrôle.</p><p>Chaque fois qu’une nuée de rats qui n’est pas sous le contrôle d’une autre créature arrive dans un rayon de 9 m de vous alors que vous jouez de la flûte, la nuée effectue un jet de sauvegarde de Sagesse DD 15. En cas de réussite, elle se comporte normalement et ne peut plus être influencée par la musique de la flûte pendant 24 heures. En cas d’échec, la nuée est envoûtée par cette mélodie et devient Amicale envers vous et vos alliés, et le reste tant que vous continuez à en jouer chaque round au prix de l’action Magie. Une nuée Amicale obéit à vos ordres. En l’absence d’instructions précises, une nuée Amicale se défend au besoin mais n’entreprend pas d’autre action. Si une nuée Amicale commence son tour à plus de 9 m de vous, votre contrôle sur elle prend fin et elle se comporte normalement. Elle ne peut alors plus être influencée par la musique de la flûte pendant 24 heures.</p>'),
  (1389, 38, 2, 0, '<p>Cette flûte dispose de 3 charges et récupère quotidiennement 1d3 charges dépensées, à l’aube. Vous pouvez entreprendre l’action Magie pour en jouer et dépenser 1 charge afin de faire naître une mélodie envoûtante. Chaque créature de votre choix dans un rayon de 9 m doit réussir un jet de sauvegarde de Sagesse DD 15 sous peine de subir l’état Effrayé pendant 1 minute. En cas d’échec, la créature peut réitérer ce JS à la fin de chacun de ses tours et met un terme à l’effet sur elle-même en cas de réussite. En cas de réussite, la créature est immunisée contre l’effet de cette flûte pendant 24 heures.</p>'),
  (1390, 38, 3, 1, '<p>Au prix de l’action Magie, vous placez au sol cette statuette en adamantium de 2,5 cm puis, en prononçant le mot de commande, provoquez sa croissance rapide en tour en adamantium de section carrée. Répéter le mot de commande fait revenir la tour à sa forme de statuette, ce qui ne fonctionne que lorsque la tour est inoccupée. Chaque créature se trouvant dans la zone où la tour apparaît est repoussée dans un espace inoccupé extérieur à la tour, mais adjacent à elle. Tout objet présent dans la zone et n’étant porté par personne est lui aussi repoussé par la tour.</p><p>La tour est large de 6 m et haute de 9 m, avec des meurtrières sur tous les flancs et un crénelage en son sommet. Son intérieur se divise en deux étages reliés par une échelle, un escalier ou un plan incliné (à votre guise). L’échelle, escalier ou plan incliné aboutit à une trappe qui ouvre sur le toit. À sa création, la tour présente une seule porte au rez-de-chaussée, orientée vers vous. Cette porte ne s’ouvre que sur votre ordre, que vous pouvez prononcer par une action Bonus. Elle est immunisée contre le sort déblocage et toute magie comparable.</p><p>Sa magie empêche la tour de basculer. Toit, porte et murs ont chacun le profil suivant : CA 20, 100 pv ; Immunité contre les dégâts contondants, perforants et tranchants sauf ceux des armes de siège ; Résistance à tous les autres dégâts. Rendre sa taille de statuette à la tour ne répare pas les dégâts qu’elle a subis. Seul le sort souhait peut réparer la tour (cette utilisation du sort compte comme la reproduction d’un sort du 8e niveau ou inférieur). Chaque incantation de souhait fait regagner tous ses points de vie à la tour.</p>'),
  (1391, 38, 2, 1, '<p>Votre Force passe à 19 tant que vous portez ces gantelets. Ils restent sans effet sur vous si votre Force est supérieure ou égale à 19 sans que vous les portiez.</p>'),
  (1392, 38, 2, 0, '<p>Une fois enfilés, ces gants sont imperceptibles. Tant que vous les portez, vous recevez un bonus de +5 à vos tests de Dextérité (Escamotage).</p>'),
  (1393, 38, 2, 1, '<p>Tant que vous portez ces gants, vous recevez une Vitesse d’escalade et une Vitesse de nage égales à votre Vitesse, ainsi qu’un bonus de +5 aux tests de Force (Athlétisme) visant à escalader ou nager.</p>'),
  (1394, 38, 2, 1, '<p>Si un jet d’attaque vous touche avec une arme à distance ou dotée de la propriété Lancer alors que vous portez ces gants, jouer votre Réaction vous permet de réduire les dégâts subis de 1d10 + votre modificateur de Dextérité à condition d’avoir une main libre. Si vous réduisez ces dégâts à 0, vous pouvez attraper l’arme (ou le projectile) si ses dimensions vous permettent de la tenir.</p>'),
  (1232, 34, 5, 1, '<p>Vous recevez un bonus de +3 aux jets d’attaque et de dégâts effectués avec cette arme magique.</p><p>La première fois que vous attaquez avec l’arme à chacun de vos tours, vous pouvez transférer tout ou partie de son bonus à votre classe d’armure. Vous pouvez par exemple réduire le bonus à vos jets d’attaque et de dégâts à +1 afin de recevoir un bonus de +2 à la CA. Les bonus ajustés restent en vigueur jusqu’au début de votre tour suivant, mais vous devez continuer à tenir l’arme pour recevoir le bonus qu’elle octroie à la CA.</p>'),
  (1395, 38, 2, 0, '<p>Ce prisme dispose de 50 charges. Tant que vous le tenez, vous pouvez consacrer l’action Magie à prononcer l’un de ses trois mots de commande afin de lui faire produire l’un des effets suivants :</p><p><b>Premier mot de commande.</b> La gemme projette une Lumière vive sur un rayon de 9 m, et une Lumière faible sur 9 m de plus. Cet effet ne consomme pas de charge. Il persiste jusqu’à ce que vous réitériez le mot de commande par une action Bonus ou que vous utilisiez une autre fonction de la gemme.</p><p><b>Deuxième mot de commande.</b> Vous dépensez 1 charge et projetez un faisceau de lumière éclatante sur une créature que vous voyez dans un rayon de 18 m. La créature doit réussir un jet de sauvegarde de Constitution DD 15 sous peine de subir l’état Aveuglé pendant 1 minute. La créature réitère le JS à la fin de chacun de ses tours et met un terme à l’effet sur elle-même en cas de réussite.</p><p><b>Troisième mot de commande.</b> Dépensez 5 charges : la gemme projette une lumière aveuglante dans un Cône de 9 m. Chaque créature prise dans le Cône effectue un jet de sauvegarde comme si elle avait été frappée par le faisceau créé avec le deuxième mot de commande.</p><p>Une fois toutes les charges de la gemme dépensées, celle-ci devient un joyau non magique d’une valeur de 50 po.</p>'),
  (1396, 38, 3, 1, '<p>Cette gemme dispose de 3 charges. Au prix de l’action Magie, vous pouvez dépenser 1 charge. Pendant les 10 prochaines minutes, vous disposez de la Vision lucide sur 36 m lorsque vous regardez à travers la gemme.</p><p>La gemme récupère quotidiennement 1d3 charges dépensées, à l’aube.</p>'),
  (1233, 34, 3, 1, '<p>Vous recevez un bonus de +1 aux jets d’attaque et de dégâts effectués avec cette arme magique. En outre et tant que vous êtes harmonisé avec cette arme, votre maximum de points de vie augmente de 1 par niveau dont vous disposez.</p><p>Malédiction. Cette arme est maudite : être harmonisé avec elle vous inflige sa malédiction. Tant que vous êtes maudit, vous refusez de vous séparer de l’arme et la gardez en permanence à portée de main. Vous subissez en outre le Désavantage aux jets d’attaque effectués avec une autre arme que celle-ci.</p><p>Chaque fois qu’une autre créature vous inflige des dégâts alors que la hache est en votre possession, vous devez réussir un jet de sauvegarde de Sagesse DD 15 sous peine de devenir fou furieux. Cet état prend fin si vous commencez votre tour sans aucune créature que vous voyez ni n’entendez dans un rayon de 18 m.</p><p>Tant que cette folie persiste, vous considérez la créature la plus proche de vous, parmi celles que vous voyez ou entendez, comme un ennemi. Si plusieurs créatures sont concernées, choisissez-en une au hasard. À chacun de vos tours, vous devez vous rapprocher le plus possible de la créature et entreprendre l’action Attaque, en prenant cette créature pour cible. Si vous ne parvenez pas à vous approcher suffisamment de la créature pour l’attaquer avec l’arme, votre tour se termine après épuisement de votre déplacement disponible. Si la créature meurt ou que vous ne la voyez et ne l’entendez plus, la plus proche créature valide parmi celles que vous voyez ou entendez devient votre nouvelle cible.</p>'),
  (1281, 35, 5, 1, '<p>Tant que vous portez cette armure, vous pouvez entreprendre l’action Magie en prononçant un mot de commande pour recevoir l’effet du sort forme éthérée. Le sort prend aussitôt fin si vous ôtez l’armure ou entreprenez l’action Magie pour répéter le mot de commande. Une fois cette propriété de l’armure utilisée, elle ne peut plus resservir avant l’aube suivante.</p>'),
  (1282, 35, 4, 0, '<p>Tant que vous portez cette armure, vous recevez un bonus de +2 à la CA. En outre, si un effet vous déplace au sol contre votre volonté, vous pouvez jouer votre Réaction pour réduire d’un maximum de 3 m la distance sur laquelle vous êtes déplacé.</p>'),
  (1401, 38, 3, 0, '<p>Ce sac à dos se compose d’une poche centrale et de deux poches latérales, chacune ouvrant sur un espace extradimensionnel. Chaque poche latérale peut contenir 100 kg de matériel pour un volume maximal de 700 litres. La poche centrale peut contenir 250 kg de matériel pour un volume maximal de 1 800 litres. Le havresac ne pèse que 2,5 kg, quel que soit son contenu.</p><p>Récupérer un objet dans le havresac nécessite l’action Utilisation ou une action Bonus (à votre guise). Lorsque vous plongez la main dans le havresac en quête d’un objet spécifique, celui-ci se trouve toujours magiquement au-dessus.</p><p>Si l’une de ses poches est surchargée, percée ou déchirée, le havresac éclate et il est détruit. Si le havresac est détruit, son contenu est perdu à jamais (un Artefact finit cependant toujours par réapparaître quelque part). Si le havresac est retourné comme un gant, son contenu se déverse sans que rien ne se brise ; il doit être remis à l’endroit avant de pouvoir être réutilisé.</p><p>Chaque poche du havresac contient suffisamment d’air pour 10 minutes de ventilation, divisées par le nombre de créatures qui respirent à l’intérieur.</p><p>Placer ce havresac dans l’espace extradimensionnel créé par un sac sans fond, un puits portable ou tout autre objet équivalent détruit instantanément les deux objets et ouvre un portail vers le Plan Astral. Ce portail s’ouvre à l’endroit où l’objet a été placé dans l’autre. Toute créature dans un rayon de 3 m du portail, si elle ne dispose pas d’un Abri total, est aspirée et déposée en un lieu aléatoire du Plan Astral. Le portail se referme alors. Il est à sens unique et ne peut pas être rouvert.</p>'),
  (1402, 38, 2, 0, '<p>Tant que vous portez ce heaume, vous pouvez lancer compréhension des langues par son biais.</p>'),
  (1403, 38, 2, 1, '<p>Tant que vous portez ce heaume, vous bénéficiez de la télépathie à une portée de 9 m, et pouvez lancer détection des pensées ou suggestion (DD de sauvegarde 13) par le biais du heaume. Dès que l’un de ces sorts a été lancé par le biais du heaume, il ne peut plus être lancé via cet objet avant l’aube suivante.</p>'),
  (1404, 38, 3, 1, '<p>Ce heaume dispose de 3 charges. Tant que vous le portez, vous pouvez dépenser 1 charge pour lancer téléportation par son biais. Le heaume récupère quotidiennement 1d3 charges dépensées, à l’aube.</p>'),
  (1405, 38, 4, 1, '<p>Ce heaume étincelant est serti de 1d10 diamants, 2d10 rubis, 3d10 opales de feu et 4d10 opales. Toute gemme extraite du heaume tombe en poussière. Lorsque toutes les gemmes ont été extraites ou détruites, le heaume perd sa magie.</p><p>Tant que vous portez ce heaume, vous recevez les bénéfices suivants :</p><p><b>Flammes d’opale de feu.</b> Tant qu’il reste au moins une opale de feu au heaume, vous pouvez consacrer l’action Magie à nimber de flammes une arme que vous tenez. Ces flammes émettent une Lumière vive dans un rayon de 3 m et une Lumière faible sur 3 m de plus. Les flammes sont inoffensives pour vous et pour l’arme. Lorsque vous touchez une cible avec l’arme enflammée, elle subit 1d6 dégâts de feu supplémentaires. Les flammes persistent jusqu’à ce que vous les éteigniez par une action Bonus ou que vous rengainiez ou lâchiez l’arme.</p><p><b>Lumière diamantine.</b> Tant qu’il lui reste au moins un diamant, le heaume diffuse une Émanation de 9 m. Lorsqu’au moins un Mort-vivant est présent dans cette zone, l’Émanation est remplie de Lumière faible. Tout Mort-vivant qui débute son tour dans cette zone subit 1d6 dégâts radiants.</p><p><b>Résistance rubis.</b> Tant qu’il reste au moins un rubis au heaume, vous bénéficiez de la Résistance aux dégâts de feu.</p><p><b>Sorts.</b> Vous pouvez lancer l’un des sorts suivants (DD de sauvegarde 18), en utilisant comme composante l’une des gemmes du heaume du type spécifié : boule de feu (opale de feu), embruns prismatiques (diamant), lumière du jour (opale) ou mur de feu (rubis). La gemme concernée est détruite et disparaît du heaume lorsque le sort est lancé.</p><p>Subir des dégâts de feu. Lancez 1d20 si vous portez le heaume et subissez des dégâts de feu après avoir raté un jet de sauvegarde contre un sort. Sur un résultat de 1, le heaume émet des faisceaux de lumière depuis les gemmes restantes, puis il est détruit. Chaque créature prise dans une Émanation de 18 m centrée sur vous doit réussir un jet de sauvegarde de Dextérité DD 17 sous peine d’être frappée par un faisceau lumineux et de subir autant de dégâts radiants que le heaume compte de gemmes.</p>'),
  (1406, 40, 4, 0, '<p>Une fiole de cette huile peut enduire une arme de corps à corps ou vingt projectiles, sachant que seules les munitions et les armes de corps à corps non magiques infligeant des dégâts perforants ou tranchants sont affectées. L’application de l’huile prend 1 minute, après quoi l’huile s’infiltre magiquement dans ce qu’elle recouvre, ce qui transforme l’arme enduite en arme +3 (les munitions enduites en projectiles +3).</p><p>Dans cette huile incolore et gélatineuse scintillent de minuscules paillettes d’argent.</p>'),
  (1407, 40, 2, 0, '<p>Une fiole de cette huile suffit à enduire une créature de taille M ou inférieure, ainsi que tout l’équipement qu’elle porte (une fiole supplémentaire est nécessaire pour chaque catégorie de taille au-dessus de M). L’application de l’huile prend 10 minutes. La créature ointe reçoit l’effet du sort liberté de mouvement pendant 8 heures.</p><p>Au lieu de cela, l’huile peut être versée au sol au prix de l’action Magie, auquel cas elle couvre un carré de 3 m et reproduit l’effet du sort graisse dans cette zone pendant 8 heures.</p><p>Cet onguent noir et gluant, épais et lourd, s’écoule pourtant très vite.</p>'),
  (1408, 40, 3, 0, '<p>Une fiole de cette huile suffit à enduire une créature de taille M ou inférieure, ainsi que tout l’équipement qu’elle porte (une fiole supplémentaire est nécessaire pour chaque catégorie de taille au-dessus de M). L’application de l’huile prend 10 minutes. La créature ointe reçoit l’effet du sort forme éthérée pendant 1 heure.</p><p>Des gouttes perlées se forment sur la paroi extérieure de ce récipient rempli d’une huile grisâtre et trouble, et s’évaporent rapidement.</p>'),
  (1409, 38, 3, 0, '<p>Tant que cette jatte est remplie d’eau et se trouve dans un rayon de 1,50 m, vous pouvez entreprendre l’action Magie pour convoquer un élémentaire de l’eau.</p><p>L’élémentaire apparaît en un espace inoccupé aussi près que possible de la jatte, comprend les mêmes langues que vous, obéit à vos ordres et joue son tour juste après vous à votre rang d’initiative. Il disparaît au bout de 1 heure, s’il meurt, ou si vous le révoquez par une action Bonus. La jatte ne peut plus être utilisée de cette manière avant l’aube suivante.</p><p>La jatte mesure environ 30 cm de diamètre et 15 de profondeur. Sa contenance est de 12 litres environ.</p>'),
  (1234, 34, 2, 0, '<p>Chaque fois que vous réussissez un jet d’attaque avec cette arme magique, vous pouvez choisir d’infliger des dégâts de foudre au lieu de dégâts perforants.</p><p>Éclair. Lorsque vous lancez cette arme sur une cible située à 36 m ou moins de vous, vous pouvez renoncer au jet d’attaque à distance pour transformer l’arme en éclair. Cet éclair forme une Ligne de 1,50 m de large entre vous et la cible. La cible et chaque créature prise dans la Ligne (vous excepté) effectuent un jet de sauvegarde de Dextérité DD 13, et subissent 4d6 dégâts de foudre en cas d’échec, la moitié en cas de réussite. Aussitôt après avoir infligé ces dégâts, l’arme réapparaît dans votre main. Cette propriété ne peut plus resservir avant l’aube suivante.</p>'),
  (1235, 34, 5, 1, '<p>Vous recevez un bonus de +1 aux jets d’attaque et de dégâts effectués avec cette arme magique. Tant que l’arme est sur vous, vous recevez en outre un bonus de +1 aux jets de sauvegarde.</p><p><b>Chance.</b> Si l’arme est sur vous et si vous ne subissez pas l’état Neutralisé, vous pouvez faire appel à sa chance (pas d’action requise) pour relancer un Test d20 raté. Vous devez garder le deuxième jet. Une fois utilisée, cette propriété ne peut plus resservir avant l’aube suivante.</p><p><b>Souhait.</b> L’arme est dotée de 1d3 charges. En la tenant, vous pouvez dépenser 1 charge et lancer souhait par son intermédiaire. Une fois utilisée, cette propriété ne peut plus resservir avant l’aube suivante. L’arme perd cette propriété quand toutes ses charges ont été dépensées.</p>'),
  (1410, 38, 2, 0, '<p>Lorsqu’elle est allumée, cette lanterne à capote brûle pendant 6 heures avec 50 cl d’huile, en projetant une Lumière vive dans un rayon de 9 m et une Lumière faible sur 9 m supplémentaires. Les créatures et objets Invisibles sont visibles sous la Lumière vive de la lanterne. Vous pouvez entreprendre l’action Utilisation pour abaisser la capote, ce qui réduit la lumière de la lanterne à une Lumière faible dans un rayon de 1,50 m.</p>'),
  (1411, 38, 2, 0, '<p>Ces lentilles en cristal s’appliquent sur les yeux. Tant que vous les portez, votre vision s’améliore nettement jusqu’à 30 cm, vous octroyant la Vision dans le noir à cette portée et l’Avantage aux tests d’Intelligence (Investigation) effectués pour examiner quelque chose à cette même portée.</p>'),
  (1412, 38, 3, 0, '<p>Cette sphère de fer rouillé, d’un diamètre de 7,5 cm, pèse 500 g. Vous pouvez entreprendre l’action Magie pour jeter la sphère sur une créature de taille TG ou inférieure que vous voyez dans un rayon de 18 m. À mesure que la sphère vole vers sa cible, elle se déplie pour former un enchevêtrement de bandes métalliques.</p><p>Effectuez un jet d’attaque à distance, le bonus d’attaque étant égal à votre modificateur de Dextérité plus votre bonus de maîtrise. Si l’attaque touche, la cible subit l’état Entravé jusqu’à ce que vous consacriez une action Bonus à la libérer d’une simple instruction. Si vous libérez la cible ou si l’attaque la rate, les bandes se contractent pour reformer la sphère.</p><p>Une créature, y compris celle qui est Entravée, peut consacrer une action à toucher les liens de fer pour effectuer un test de Force (Athlétisme) DD 20 afin de les briser. En cas de réussite, l’objet est détruit et la créature Entravée est libérée. En cas d’échec, toutes les autres tentatives de cette même créature échouent automatiquement jusqu’à ce que 24 heures se soient écoulées.</p><p>Une fois ces liens utilisés, ils ne peuvent plus resservir avant l’aube suivante.</p>'),
  (1413, 38, 2, 0, '<p>Tant que vous chaussez ces lunettes teintées, vous bénéficiez de la Vision dans le noir à 18 m. Si vous disposiez déjà de la Vision dans le noir, le port de ces lunettes en augmente la portée de 18 m.</p>'),
  (1414, 38, 3, 1, '<p>Vous avez l’Avantage aux jets de sauvegarde contre les sorts quand vous portez ce manteau.</p>'),
  (1415, 38, 4, 0, '<p>Ce livre aux inscriptions chargées de magie dispense de précieux conseils en matière d’exercices physiques. Si vous consacrez 48 heures sur une période maximale de 6 jours à étudier le contenu de l’ouvrage et à le mettre en pratique, votre valeur de Force augmente de 2, jusqu’à un maximum de 30. Le manuel perd alors sa magie, mais la retrouve après un siècle.</p>'),
  (1416, 38, 4, 0, '<p>Ce livre aux inscriptions chargées de magie dispense de précieux conseils en matière de santé et de nutrition. Si vous consacrez 48 heures sur une période maximale de 6 jours à étudier le contenu de l’ouvrage et à le mettre en pratique, votre valeur de Constitution augmente de 2, jusqu’à un maximum de 30. Le manuel perd alors sa magie, mais la retrouve après un siècle.</p>'),
  (1417, 38, 4, 0, '<p>Ce livre aux inscriptions chargées de magie dispense de précieux conseils en matière d’exercices de coordination et d’équilibre. Si vous consacrez 48 heures sur une période maximale de 6 jours à étudier le contenu de l’ouvrage et à le mettre en pratique, votre valeur de Dextérité augmente de 2, jusqu’à un maximum de 30. Le manuel perd alors sa magie, mais la retrouve après un siècle.</p>'),
  (1418, 38, 4, 0, '<p>Cet ouvrage renferme les informations et incantations nécessaires à l’assemblage d’un type spécifique de golem. Le MJ en choisit le type ou le détermine aléatoirement selon la table suivante. Pour déchiffrer et utiliser ce manuel, vous devez être un incantateur disposant d’au moins deux emplacements de sort du 5e niveau. Une créature incapable d’utiliser le manuel des golems et qui tente de le lire subit 6d6 dégâts psychiques.</p><p>Pour créer un golem, vous devez consacrer le nombre de jours indiqué sur la table et travailler sans relâche avec le manuel à portée de main sans prendre plus de 8 heures de Repos par jour. Vous devez également acquitter le coût indiqué pour acheter les matériaux nécessaires.</p><p>Une fois la création du golem terminée, des flammes mystiques dévorent le livre. Le golem s’anime lorsque les cendres du manuel sont dispersées sur lui. Reportez-vous à « Monstres » pour le profil de jeu du golem. Il est sous votre contrôle, vous comprend et obéit à vos ordres.</p><p>1d20 1–5 6–17 18 19–20</p><p>Golem Golem d’argile Golem de chair Golem de fer Golem de pierre</p><p>Temps 30 jours 60 jours 120 jours 90 jours</p><p>Prix 65 000 po 50 000 po 100 000 po 80 000 po</p>'),
  (1239, 34, 5, 1, '<p>Vous recevez un bonus de +1 aux jets d’attaque et de dégâts effectués avec cette arme magique.</p><p><b>L’arme dispose de 5 charges.</b> Vous pouvez dépenser 1 charge et effectuer une attaque à distance avec cette arme, en la lançant comme si elle était dotée de la propriété Lancer avec une portée normale de 6 m et une portée longue de 18 m. Si l’attaque touche, l’arme fait retentir un coup de tonnerre audible dans un rayon de 90 m. La cible et toutes les créatures dans un rayon de 9 m d’elle doivent réussir un jet de sauvegarde de Constitution DD 17 sous peine de subir l’état Étourdi jusqu’à la fin de votre tour suivant. Aussitôt après avoir touché ou raté sa cible, l’arme revient dans votre main. L’arme récupère quotidiennement 1d4 + 1 charges dépensées, à l’aube.</p><p><b>Souveraineté gigante.</b> Tant que persiste votre Harmonisation avec l’arme et que vous portez un ceinturon de force de géant ou des gantelets de puissance d’ogre également soumis à votre Harmonisation, vous recevez les bénéfices suivants :</p><p><b>Fléau des géants.</b> Lorsque vous obtenez un 20 sur le d20 d’un jet d’attaque effectué avec cette arme contre un Géant, la créature doit réussir un jet de sauvegarde de Constitution DD 17 sous peine de mourir sur le coup.</p><p><b>Puissance gigante.</b> La valeur de Force octroyée par votre ceinturon de force de géant ou vos gantelets de puissance d’ogre augmente de 4, jusqu’à un maximum de 30.</p>'),
  (1240, 34, 4, 1, '<p><em>Harmonisation requise avec un nain ou une créature harmonisée avec un ceinturon des nains</em></p><p>Vous recevez un bonus de +3 aux jets d’attaque et de dégâts effectués avec cette arme magique. Elle est dotée de la propriété Lancer avec une portée normale de 6 m et une portée longue de 18 m. Lorsque vous touchez avec une attaque à distance à l’aide de cette arme, celle-ci inflige 1d8 dégâts de force supplémentaires (2d8 si la cible est un Géant). Aussitôt après avoir touché ou raté sa cible, l’arme revient dans votre main.</p>'),
  (1236, 34, 3, 1, '<p>Quand vous touchez un Fiélon ou un Mort-vivant avec cette arme magique, cette créature subit 2d6 dégâts radiants supplémentaires. S’il reste 25 points de vie ou moins à la cible après application de ces dégâts, elle doit réussir un jet de sauvegarde de Sagesse DD 15 sous peine d’être détruite. En cas de réussite, la créature subit toutefois l’état Effrayé jusqu’à la fin de votre tour suivant.</p><p>Lumière. Tant que vous tenez cette arme en main, elle émet une Lumière vive sur un rayon de 6 m et une Lumière faible sur 6 m de plus.</p>'),
  (1237, 34, 3, 0, '<p>Vous recevez un bonus de +1 aux jets d’attaque et de dégâts effectués avec cette arme magique. Ce bonus passe à +3 lorsque vous utilisez l’arme pour attaquer un Artificiel.</p><p>Lorsque vous obtenez un 20 sur un jet d’attaque effectué avec cette arme, la cible subit 7 dégâts contondants supplémentaires, ou 14 dégâts contondants supplémentaires s’il s’agit d’un Artificiel. Tout Artificiel qui se retrouve avec 25 points de vie ou moins après application de ces dégâts est détruit.</p>'),
  (1238, 34, 3, 1, '<p>Cette arme magique dispose de 3 charges et récupère quotidiennement 1d3 charges dépensées, à l’aube. En tenant l’arme, vous pouvez entreprendre l’action Magie et dépenser 1 charge pour en libérer une vague de terreur. Chaque créature de votre choix dans un rayon de 9 m doit réussir un jet de sauvegarde de Sagesse DD 15 sous peine de subir l’état Effrayé pendant 1 minute. Une créature ainsi Effrayée doit consacrer ses tours à tenter de s’éloigner le plus possible de vous, et elle ne peut pas effectuer d’attaques d’Opportunité. Dans le cadre d’une action, elle ne peut entreprendre que Pointe ou tenter de se libérer d’un effet qui l’empêche de se déplacer. Si elle n’a nulle part où aller, elle peut entreprendre l’action Esquive. La créature réitère le JS à la fin de chacun de ses tours et met un terme à l’effet sur elle-même en cas de réussite.</p>'),
  (1241, 34, 4, 1, '<p>Tant que persiste votre Harmonisation avec cette arme magique, votre Force est de 20, à moins qu’elle soit déjà égale ou supérieure à cette valeur. L’arme inflige 1d8 dégâts de tonnerre supplémentaires à toute créature qu’elle touche, et 3d8 dégâts de tonnerre supplémentaires aux objets qu’elle touche et qui ne sont portés par personne.</p><p>L’arme est dotée des propriétés supplémentaires suivantes.</p><p><b>Coup de tonnerre.</b> Au prix de l’action Magie, vous pouvez frapper l’arme contre une surface dure pour créer un puissant coup de tonnerre audible à 90 m. Vous générez également un Cône d’énergie tonitruante de 9 m. Chaque créature prise dans le Cône doit réussir un jet de sauvegarde de Force DD 15 sous peine de subir l’état À terre. Dans ce Cône, les objets non magiques qui ne sont portés par personne subissent 3d8 dégâts de tonnerre.</p><p><b>Tremblement de terre.</b> Au prix de l’action Magie, vous pouvez frapper l’arme contre le sol pour déclencher une intense perturbation sismique dans un cercle de 15 m de rayon centré sur le point d’impact. Les structures en contact avec le sol de cette zone subissent 50 dégâts contondants, et chaque créature touchant le sol de la zone doit réussir un jet de sauvegarde de Dextérité DD 20 sous peine de subir l’état À terre. Une créature qui se concentre doit également réussir un jet de sauvegarde de Constitution DD 20 sous peine de perdre sa Concentration. Vous pouvez en outre ouvrir une faille de 9 m de profondeur et 3 m de large n’importe où dans la zone. Toute créature se trouvant à cet endroit effectue un jet de sauvegarde de Dextérité DD 20. Elle tombe dans la faille en cas d’échec, et parvient à se décaler au bord du gouffre en cas de réussite. Toute structure située à l’endroit où s’ouvre la faille s’effondre dans celle-ci. Une fois cette propriété utilisée, vous ne pouvez plus y recourir avant l’aube suivante.</p>'),
  (1419, 38, 2, 1, '<p>Ce médaillon dispose de 5 charges. Lorsque vous le portez, vous pouvez dépenser 1 charge pour lancer détection des pensées (DD de sauvegarde 13) par son intermédiaire. Le médaillon récupère quotidiennement 1d4 charges dépensées, à l’aube.</p>'),
  (1420, 38, 3, 0, '<p>L’action Utilisation vous permet d’employer cet objet pour menotter une créature subissant l’état Neutralisé. Les menottes s’ajustent à toute créature de taille P, M ou G. Ces menottes empêchent la créature menottée de recourir à tout moyen de déplacement extradimensionnel, y compris la téléportation ou le voyage vers un autre plan d’existence. Elles n’empêchent toutefois pas la créature de traverser un portail interdimensionnel.</p><p>Vous-même et toute créature que vous désignez lorsque vous utilisez ces menottes pouvez consacrer l’action Utilisation à les retirer. Une fois tous les 30 jours, la créature menottée peut effectuer un test de Force (Athlétisme) DD 30. En cas de réussite, elle se libère et détruit les menottes.</p>'),
  (1421, 38, 4, 0, '<p>Quand on regarde indirectement dans ce miroir de 1,20 m de haut pour 60 cm de large, on y distingue des reflets fugitifs de créatures. Le miroir pèse 25 kg avec le profil suivant : CA 11, 10 pv, Immunité contre les dégâts psychiques et de poison, Vulnérabilité aux dégâts contondants. Réduit à 0 point de vie, il se brise en mille morceaux, définitivement détruit.</p><p>Si le miroir est accroché à une surface verticale et que vous vous trouvez à 1,50 m ou moins de lui, vous pouvez entreprendre l’action Magie et prononcer un mot de commande pour l’activer. Il reste activé jusqu’à ce que vous entrepreniez l’action Magie et répétiez le mot de commande pour le désactiver.</p><p>Toute créature autre que vous qui voit son reflet dans le miroir activé alors qu’elle se tient dans un rayon de 9 m de l’objet doit réussir un jet de sauvegarde de Charisme DD 15 sous peine d’être emprisonnée, avec tout ce qu’elle porte, dans l’un des douze cachots extradimensionnels du miroir. Une créature qui connaît la nature du miroir effectue ce jet de sauvegarde avec l’Avantage, tandis que les Artificiels réussissent automatiquement le JS.</p><p>Un cachot extradimensionnel est un espace infini dans lequel flotte un épais brouillard qui réduit la visibilité à 3 m. Les créatures prisonnières du miroir peuvent se passer de nourriture, de boisson et de sommeil et elles ne vieillissent pas. Une créature prisonnière d’un cachot peut s’en échapper si elle recourt à une magie qui permet de voyager entre les plans. Dans le cas contraire, cette créature est prisonnière du cachot jusqu’à ce qu’elle en soit libérée.</p><p>Si le miroir piège une créature alors que ses douze cachots extradimensionnels sont occupés, l’objet libère au hasard une créature emprisonnée pour accueillir le nouveau prisonnier. Une créature libérée apparaît dans un espace inoccupé en vue du miroir, mais de dos par rapport à lui. Si le miroir est brisé, toutes les créatures qu’il emprisonne sont libérées et apparaissent dans des espaces inoccupés à proximité.</p><p>Dans un rayon de 1,50 m du miroir, vous pouvez entreprendre l’action Magie pour prononcer le nom d’une créature emprisonnée ou le numéro d’un cachot. La créature nommée ou prisonnière du cachot annoncé apparaît sous la forme d’un reflet à la surface du miroir. Vous-même et la créature pouvez alors communiquer.</p><p>De même, vous pouvez entreprendre l’action Magie et utiliser un second mot de commande pour libérer une créature piégée dans le miroir. La créature libérée apparaît, avec tout son équipement, dans l’espace inoccupé le plus proche du miroir, en lui tournant le dos.</p><p>Placer le miroir dans un espace extradimensionnel créé par un sac sans fond, un puits portable ou un objet similaire détruit instantanément les deux objets et ouvre un portail vers le Plan Astral. Ce portail s’ouvre à l’endroit où l’objet a été placé dans l’autre. Toute créature dans un rayon de 3 m du portail, si elle ne dispose pas d’un Abri total, est aspirée et se retrouve en un lieu aléatoire du Plan Astral. Le portail se referme alors. Il est à sens unique et ne peut pas être rouvert.</p>'),
  (1422, 38, 6, 1, '<p>Chaque orbe est un globe de cristal gravé d’environ 25 cm de diamètre. Lorsqu’il est utilisé, il enfle pour atteindre un diamètre d’environ 50 cm, tandis que de la brume tourbillonne à l’intérieur.</p><p>Une fois harmonisé avec l’orbe, vous pouvez entreprendre l’action Magie pour scruter ses profondeurs insondables. Effectuez un jet de sauvegarde de Charisme DD 15. En cas de réussite, vous contrôlez l’orbe aussi longtemps que l’harmonisation persiste. Un échec, en revanche, vous place sous l’emprise de l’Artefact en vous imposant l’état Charmé pour toute la durée de l’Harmonisation.</p><p>Tant que vous êtes Charmé par l’orbe, vous ne pouvez pas volontairement mettre fin à cette Harmonisation et l’orbe lance suggestion sur vous à volonté (sauvegarde DD 18) en vous pressant d’œuvrer à ses desseins maléfiques. Les désirs de l’essence du dragon peuvent prendre bien des formes : anéantir un groupe spécifique, libérer l’orbe, répandre la souffrance dans le monde, faire prospérer le culte de Tiamat ou tout autre sombre dessein imaginé par le MJ.</p><p><b>Sorts.</b> L’orbe dispose de 7 charges et récupère quotidiennement 1d4 + 3 charges dépensées, à l’aube. Si vous contrôlez l’orbe, vous pouvez lancer l’un des sorts de la table suivante. La table indique le nombre de charges à dépenser pour lancer le sort.</p><p>Sort</p><p>Coût en charges détection de la magie lumière du jour protection contre la mort scrutation (DD de sauvegarde 18) soins (au 9e niveau)</p><p><b>Appel des dragons.</b> Tant que vous contrôlez l’orbe, vous pouvez, au prix de l’action Magie, émettre par son biais un appel télépathique qui s’étend dans toutes les directions sur 60 km. Les dragons chromatiques à portée sont contraints de venir vers l’orbe au plus vite et par l’itinéraire le plus direct. Les divinités draconiques, comme Tiamat, ne sont pas affectées par cet appel. Les dragons chromatiques attirés par l’orbe peuvent se montrer Hostiles envers vous pour les avoir contraints à venir. Une fois utilisée, cette propriété ne peut plus resservir pendant 1 heure.</p><p><b>Destruction d’un orbe.</b> Un Orbe draconique est doté d’une CA de 20 et ne peut être détruit que s’il subit des dégâts d’une arme +3 ou du sort désintégration. Nulle autre force ne saurait l’entamer.</p>'),
  (1423, 38, 3, 0, '<p>Cette petite sphère noire de 2 cm de diamètre pèse environ 30 g. Les perles de force se trouvent généralement par poignée de 1d4 + 4.</p><p>Entreprendre l’action Magie permet de lancer la perle à une distance maximale de 18 m. La perle provoque une explosion à l’impact dans une Sphère de 3 m de rayon, ce qui la détruit. Chaque créature prise dans la Sphère doit réussir un jet de sauvegarde de Dextérité DD 15, sous peine de subir 5d4 dégâts de force. Une sphère de force transparente entoure la zone pendant 1 minute. Toute créature ayant raté le JS, si elle se trouve entièrement dans la zone, est piégée à l’intérieur de cette sphère. Les créatures qui ont réussi leur sauvegarde ou qui ne sont que partiellement dans la zone sont repoussées depuis le centre de la sphère jusqu’à se retrouver entièrement en dehors. Seul l’air respirable peut traverser la paroi de la sphère. Les attaques et autres effets, quels qu’ils soient, en sont incapables.</p><p>Une créature piégée peut entreprendre l’action Utilisation pour pousser sur la paroi de la sphère, ce qui la fait rouler à concurrence de la moitié de sa propre Vitesse. On peut ramasser la sphère, qui ne pèse que 500 g en raison de sa magie, quel que soit le poids des créatures piégées à l’intérieur.</p>'),
  (1424, 38, 2, 1, '<p><em>Harmonisation requise avec un incantateur</em></p><p>Tant que cette perle est sur vous, vous pouvez entreprendre l’action Magie pour récupérer un emplacement de sort dépensé du 3e niveau ou inférieur. Une fois la perle utilisée, vous ne pouvez plus y recourir avant l’aube suivante.</p>'),
  (1425, 38, 1, 0, '<p>Cette perle gélatineuse sans saveur fond sur la langue et fournit l’équivalent nutritif de 1 jour de rations.</p>'),
  (1494, 40, 2, 0, '<p>La première fois que vous voyez une créature dans les 10 minutes après avoir bu ce philtre, vous êtes séduit par cette créature et recevez l’état Charmé pendant 1 heure.</p><p>Ce liquide rosé effervescent contient une imperceptible bulle en forme de cœur.</p>'),
  (1426, 38, 3, 0, '<p>En maintenant le contact avec cette pierre posée au sol de 2,5 kg, vous pouvez entreprendre l’action Magie pour convoquer un élémentaire de la terre. L’élémentaire apparaît en un espace inoccupé de votre choix dans un rayon de 9 m, obéit à vos ordres et joue son tour aussitôt après vous dans l’ordre d’Initiative. Il disparaît au bout de 1 heure ; plus tôt s’il meurt ou si vous le révoquez par une action Bonus. La pierre ne peut plus resservir de cette manière avant l’aube suivante.</p>'),
  (1441, 38, 2, 1, '<p>Tant que vous portez sur vous cette agate polie, vous recevez un bonus de +1 aux tests de caractéristique et aux jets de sauvegarde.</p>'),
  (1442, 38, 2, 0, '<p>Les pierres messagères vont par deux, les motifs ciselés à la surface de chacune étant assortis et facilement reconnaissables. En tenant l’une des pierres, vous pouvez lancer communication à distance par son biais. La cible du sort est le porteur de l’autre pierre. Si aucune créature ne porte l’autre pierre, vous l’apprenez dès que vous cherchez à vous servir de la vôtre, et vous ne lancez pas le sort.</p><p>Une fois que communication à distance est lancé par l’une des pierres, celles-ci ne peuvent plus resservir avant l’aube suivante. Si l’une des pierres de la paire est détruite, l’autre devient non magique.</p>'),
  (1443, 38, 4, 0, '<p>Cette belle boîte en bois contient 1d4 pots de pigments et un pinceau (pour un poids total de 500 g).</p><p>En utilisant le pinceau et en dépensant 1 pot de pigments, vous pouvez peindre un nombre illimité d’objets tridimensionnels et d’éléments de terrain (tels que murs, portes, arbres, fleurs, armes, toiles d’araignée et fosses), à condition que ces éléments tiennent tous dans un Cube de 6 m. L’opération prend 10 minutes (quel que soit le nombre d’éléments que vous créez), pendant lesquelles vous devez rester dans le Cube, et nécessite votre Concentration. Si votre Concentration est rompue ou que vous quittez le Cube avant que le travail ne soit terminé, tous les éléments peints disparaissent et le pot de pigments est gaspillé.</p><p>Une fois le travail terminé, tous les objets et éléments de terrain peints deviennent réels. Ainsi, peindre une porte sur un mur crée-t-il une vraie porte qu’on peut ouvrir sur ce qui se trouve au-delà du mur. Peindre une fosse crée une véritable fosse, dont la profondeur totale doit se trouver dans le Cube de 6 m.</p><p>Aucun objet créé par un pot de pigments ne peut avoir une valeur supérieure à 25 po, tandis que la valeur totale de tous les objets créés par un même pot de pigments ne peut dépasser 500 po. Si vous tracez des objets de plus grande valeur (comme un gros tas d’or), ils paraissent authentiques, mais un examen attentif révèle qu’ils sont faits de pâte, de biscuits ou de quelque autre matériau sans valeur.</p><p>Si vous peignez une forme d’énergie comme le feu ou la foudre, l’énergie se dissipe sitôt la peinture achevée, sans rien endommager.</p>'),
  (1495, 40, 2, 0, '<p>Lorsque vous buvez cette potion, vous recevez l’effet « agrandissement » du sort agrandissement/rapetissement pendant 10 minutes (aucune Concentration requise).</p><p>La partie rouge du liquide de la potion se dilate et se contracte en boucle, d’une petite perle colorant le liquide incolore et vice-versa. Le processus ne s’interrompt pas, même quand on secoue la bouteille.</p>'),
  (1496, 40, 2, 0, '<p>Lorsque vous buvez cette potion, vous pouvez lancer le sort amitié avec les animaux au 3e niveau (DD de sauvegarde 13).</p><p>Agiter ce liquide trouble permet de distinguer les menus objets qui y flottent : écaille de poisson, plume de colibri, griffe de chat, poil d’écureuil.</p>'),
  (1497, 40, 1, 0, '<p>Lorsque vous buvez cette potion, vous recevez une Vitesse d’escalade égale à votre Vitesse pendant</p><p>1 heure. Pendant cette heure, vous avez l’Avantage aux tests de Force (Athlétisme) effectués pour l’escalade.</p><p>La potion est divisée en nappes brunes, argentées et grises évoquant des strates dans la roche. Ces couleurs ne se mélangent pas, même quand on secoue la bouteille.</p>'),
  (1498, 40, 3, 0, '<p>Lorsque vous buvez cette potion, vous recevez 10 points de vie temporaires qui persistent 1 heure. Pendant cette heure, vous êtes sous l’effet du sort bénédiction (aucune Concentration requise).</p><p>Ce liquide bleu bouillonne et fume comme s’il était en ébullition.</p>'),
  (1499, 40, 3, 0, '<p>Le récipient de cette potion paraît vide, tout en donnant étrangement l’impression de contenir un liquide. Lorsque vous buvez la potion, vous recevez l’état Invisible pendant 1 heure. Cet effet prend fin prématurément si vous effectuez un jet d’attaque, infligez des dégâts ou lancez un sort.</p>'),
  (1500, 40, 3, 0, '<p>Pendant 1 minute après avoir bu cette potion, vous bénéficiez de la Résistance à tous les dégâts.</p><p>Ce liquide sirupeux ressemble à du fer liquide.</p>'),
  (1501, 40, 3, 0, '<p>Lorsque vous buvez cette potion, vous recevez l’effet du sort clairvoyance (aucune Concentration requise).</p><p>Le globe oculaire qui flotte dans ce liquide jaunâtre disparaît quand la potion est ouverte.</p>'),
  (1502, 40, 3, 0, '<p>Lorsque vous buvez cette potion, vous recevez l’effet « rapetissement » du sort agrandissement/rapetissement pendant 1d4 heures (aucune Concentration requise).</p><p>La partie rouge du liquide de la potion se contracte continuellement en une boule minuscule, puis se dilate pour colorer le fluide incolore qui l’entoure. Le processus ne s’interrompt pas, même quand on secoue la bouteille.</p>'),
  (1508, 40, 3, 0, '<p>Lorsque vous buvez cette potion, vous recevez l’effet du sort forme gazeuse pendant 1 heure (aucune Concentration requise) ou jusqu’à ce que vous mettiez fin à cet effet par une action Bonus.</p><p>Le récipient de cette potion semble contenir du brouillard dont la fluidité est cependant celle de l’eau.</p>'),
  (1513, 40, 3, 0, '<p>Lorsque vous buvez cette potion, vous recevez l’effet du sort détection des pensées (DD de sauvegarde 13) pendant 10 minutes (aucune Concentration requise).</p><p>Dans ce liquide dense et pourpre flotte un nuage ovoïde et rose.</p>'),
  (1524, 40, 2, 0, '<p>Vous pouvez respirer sous l’eau pendant 24 heures après avoir bu cette potion.</p><p>Ce liquide vert laiteux, dans lequel flotte une bulle aux allures de méduse (acalèphe), dégage des senteurs marines.</p>'),
  (1525, 40, 4, 0, '<p>Lorsque vous buvez cette potion, elle supprime tous vos niveaux d’Épuisement et met fin à l’éventuel état Empoisonné qui vous affecte. Pendant 24 heures, vous récupérez le maximum de points de vie pour chaque dé de vie dépensé.</p><p>Ce liquide cramoisi palpite régulièrement d’une lueur sourde, tel un battement de cœur.</p>'),
  (1526, 40, 4, 0, '<p>Lorsque vous buvez cette potion, vous recevez l’effet du sort hâte pendant 1 minute (aucune Concentration requise) sans subir la vague de léthargie qui survient habituellement à la fin de l’effet.</p><p>Le liquide jaune de la potion, strié de noir, tourbillonne sans qu’on l’agite.</p>'),
  (1527, 40, 4, 0, '<p>Lorsque vous buvez cette potion, vous recevez une Vitesse de vol égale à votre Vitesse pendant 1 heure et pouvez évoluer en vol stationnaire. Si vous êtes en vol au moment où la potion cesse de faire effet, vous tombez si vous ne disposez d’aucun autre moyen de vous maintenir dans les airs.</p><p>Le liquide translucide de cette potion flotte dans la partie supérieure du récipient, troublé par des impuretés blanches.</p>'),
  (1528, 40, 2, 0, '<p>Cette décoction a l’apparence, l’odeur et le goût d’une potion de guérison ou d’une autre potion bénéfique. Il s’agit toutefois d’un poison masqué par quelque illusion magique. Le sort identification révèle sa véritable nature.</p><p>Si vous en buvez le contenu, vous subissez 4d6 dégâts de poison et devez réussir un jet de sauvegarde de Constitution DD 13 sous peine de subir l’état Empoisonné pendant 1 heure.</p>'),
  (1450, 38, 2, 0, '<p>Trouvée dans un petit récipient, cette fine poudre ressemble à de la poussière de disparition, même le sort identification la percevant comme telle. Il y en a assez pour une utilisation.</p><p>Au prix de l’action Utilisation, vous pouvez lancer cette poudre en l’air, ce qui vous soumet ainsi que chaque créature prise dans une Émanation de 9 m centrée sur vous à un jet de sauvegarde de Constitution DD 15. Artificiels, Élémentaires, Morts-vivants, Plantes et Vases réussissent automatiquement ce JS.</p><p>En cas d’échec, une créature se met à éternuer de façon incontrôlable ; elle subit l’état Neutralisé et s’asphyxie. La créature réitère le JS à la fin de chacun de ses tours et met un terme à l’effet sur elle-même en cas de réussite. L’effet prend également fin sur toute créature cible du sort restauration partielle.</p>'),
  (1451, 38, 2, 0, '<p>Cette petite pochette contient 1d6 + 4 pincées de poudre. Au prix de l’action Utilisation, vous dispersez une pincée de cette poudre sur de l’eau, transformant un Cube d’eau de 4,50 m en une boulette de la taille d’une bille, qui flotte ou repose près de l’endroit où la poudre a été appliquée. Le poids de la boulette est négligeable. Une créature qui consacre l’action Utilisation à projeter violemment la boulette contre une surface dure provoque son éclatement, ce qui libère la quantité d’eau absorbée par la poudre. Ce faisant, la boulette est détruite et met fin à sa magie.</p><p>Au prix de l’action Utilisation, vous pouvez disperser une pincée de cette poudre sur un Élémentaire essentiellement composé d’eau (par exemple un élémentaire de l’eau) situé dans un rayon de 1,50 m. Exposée à une pincée de poudre, une telle créature effectue un jet de sauvegarde de Constitution DD 13 et subit 10d6 dégâts nécrotiques en cas d’échec, la moitié en cas de réussite.</p>'),
  (1452, 38, 2, 0, '<p>Cette poudre ressemble à du sable fin. Il y en a assez pour une utilisation. Lorsque vous entreprenez l’action Utilisation pour lancer la poudre en l’air, vous-même et chaque créature ou objet pris dans une Émanation de 3 m centrée sur vous recevez l’état Invisible pendant 2d4 minutes. La durée est la même pour tous les sujets, et la poussière est détruite quand sa magie s’active. Aussitôt après qu’une créature affectée effectue un jet d’attaque, inflige des dégâts ou lance un sort, l’état Invisible prend fin pour elle.</p>'),
  (1250, 34, 4, 0, '<p>Ce projectile magique est conçu pour tuer les créatures d’un type donné, que le MJ choisit ou détermine aléatoirement selon la table ci-après. Si la créature de ce type subit des dégâts du projectile, elle effectue un jet de sauvegarde de Constitution DD 17 et subit 6d10 dégâts de force supplémentaires en cas d’échec, la moitié en cas de réussite.</p><p>Après avoir infligé ces dégâts supplémentaires à une créature, le projectile devient non magique.</p><p>Type de 1d100 créature 01–10 Aberrations 11–15 Artificiels 16–20 Bêtes 21–25 Célestes 26–35 Dragons 36–45 Élémentaires 46–55 Fées</p><p>Type de 1d100 créature 56–65 Fiélons 66–70 Géants 71–75 Humanoïdes 76–80 Monstruosités 81–90 Morts-vivants 91–95 Plantes 96–00 Vases</p>'),
  (1453, 38, 5, 0, '<p>Ce pan d’étoffe noire et précieuse, aussi douce que de la soie, est plié aux dimensions d’un mouchoir de poche. Déplié, il forme un cercle de 1,80 m de diamètre.</p><p>Vous pouvez entreprendre l’action Magie pour déplier le puits des mondes en le plaçant sur une surface solide, où il forme un portail circulaire bidirectionnel de 1,80 m de diamètre vers un autre monde ou plan d’existence. Chaque fois que l’objet ouvre un portail, le MJ décide où il mène. Le portail reste ouvert jusqu’à ce qu’une créature dans un rayon de 1,50 m entreprenne l’action Magie pour le fermer en saisissant les bords du tissu et en le repliant.</p><p>Une fois que le puits des mondes a ouvert un portail, il ne peut plus en rouvrir d’autres pendant 1d8 heures.</p>'),
  (1454, 38, 3, 0, '<p>Ce pan d’étoffe noire et précieuse, aussi douce que de la soie, est plié aux dimensions d’un mouchoir de poche. Déplié, il forme un cercle de 1,80 m de diamètre.</p><p>Vous pouvez entreprendre l’action Magie pour déplier un puits portable et le placer sur ou contre une surface solide. Le puits portable crée alors un trou extradimensionnel de 3 m de profondeur. L’espace cylindrique à l’intérieur du puits, qui existe sur un plan d’existence différent, ne peut pas être utilisé pour créer un passage.</p><p>Toute créature à l’intérieur d’un puits portable ouvert peut en sortir en escaladant la paroi.</p><p>Vous pouvez consacrer l’action Magie à refermer un puits portable en saisissant les bords de l’étoffe et en le repliant. Plier le tissu ferme le puits. Toutes les créatures et tous les objets qu’il contient restent dans l’espace extradimensionnel. Quoi qu’il renferme, le puits ne pèse presque rien.</p><p>Si le puits est replié, une créature à l’intérieur de l’espace extradimensionnel peut consacrer une action à effectuer un test de Force (Athlétisme) DD 10. En cas de réussite, elle se fraie un chemin et apparaît dans un rayon de 1,50 m du puits portable. Un puits portable fermé contient suffisamment d’air pour 1 heure de ventilation, à diviser par le nombre de créatures qui respirent à l’intérieur.</p><p>Placer un puits portable dans l’espace extradimensionnel créé par un sac sans fond, un havresac magique ou tout autre objet comparable détruit instantanément les deux objets et ouvre un portail vers le Plan Astral. Ce portail s’ouvre à l’endroit où l’objet a été placé dans l’autre. Toute créature dans un rayon de 3 m du portail, si elle ne dispose pas d’un Abri total, est aspirée et déposée en un lieu aléatoire du Plan Astral. Le portail se referme alors. Il est à sens unique et ne peut pas être rouvert.</p>'),
  (1455, 38, 2, 1, '<p>Ces lentilles en cristal s’appliquent sur les yeux. Elles disposent de 3 charges. Tant que vous les portez, vous pouvez dépenser 1 ou plusieurs charges pour lancer charme-personne (DD de sauvegarde 13). Avec 1 charge, vous lancez le sort au 1er niveau. Chaque charge supplémentaire que vous dépensez augmente de 1 le niveau du sort. Les lentilles récupèrent quotidiennement toutes les charges dépensées, à l’aube.</p>'),
  (1456, 38, 4, 1, '<p>De petites étoiles blanches et argentées sont brodées sur cette robe noire ou bleu nuit. Vous recevez un bonus de +1 aux jets de sauvegarde tant que vous la portez.</p><p>Six étoiles, situées sur la face avant de la robe, au niveau du col, sont plus grandes que les autres. Tant que vous portez cette robe, vous pouvez entreprendre l’action Magie pour retirer l’une des étoiles et la dépenser afin de lancer projectile magique au 5e niveau. Chaque jour au crépuscule, 1d6 étoiles ainsi retirées réapparaissent sur la robe.</p><p>Lorsque vous portez la robe, vous pouvez entreprendre l’action Magie pour entrer dans le Plan Astral avec tout ce que vous portez. Vous y restez jusqu’à ce que vous entrepreniez l’action Magie pour retourner sur le plan d’existence où vous étiez auparavant. Vous réapparaissez dans le dernier espace que vous occupiez ou, si celui-ci n’est plus libre, dans l’espace inoccupé le plus proche.</p>'),
  (1457, 38, 5, 1, '<p><em>Harmonisation requise avec un Ensorceleur, Magicien ou Occultiste</em></p><p>Ce vêtement élégant est fait d’une superbe étoffe ornée de runes.</p><p>Tant que vous portez cette robe, vous recevez les bénéfices suivants :</p><p><b>Armure.</b> Si vous ne portez pas d’armure, votre classe d’armure de base est égale à 15 + votre modificateur de Dextérité.</p><p><b>Magie de guerre.</b> Votre DD de sauvegarde des sorts et votre bonus d’attaque de sort augmentent chacun de 2.</p><p><b>Résistance à la magie.</b> Vous avez l’Avantage aux jets de sauvegarde contre les sorts et autres effets magiques.</p>'),
  (1458, 38, 3, 1, '<p>Cette robe est ornée de motifs représentant des yeux. Tant que vous la portez, vous recevez les bénéfices suivants :</p><p><b>Sens spéciaux.</b> Vous disposez de la Vision dans le noir et de la Vision lucide sur 36 m.</p><p><b>Vision panoramique.</b> La robe vous confère l’Avantage aux tests de Sagesse (Perception) qui reposent sur la vue.</p><p><b>Inconvénients.</b> Le sort lumière lancé sur la robe ou le sort lumière du jour lancé dans un rayon de 1,50 m du vêtement vous fait subir l’état Aveuglé pendant 1 minute. À la fin de chacun de vos tours, vous pouvez effectuer un jet de sauvegarde de Constitution (DD 11 pour lumière, DD 15 pour lumière du jour) et mettez fin à cet état en cas de réussite.</p>'),
  (1459, 38, 2, 0, NULL),
  (1460, 38, 4, 1, '<p>Cette robe dispose de 3 charges et récupère quotidiennement 1d3 charges dépensées, à l’aube. Lorsque vous la portez, vous pouvez entreprendre l’action Magie et dépenser 1 charge pour y faire apparaître un motif changeant de teintes éblouissantes, jusqu’à la fin de votre tour suivant. Pendant cet intervalle, elle produit une Lumière vive sur un rayon de 9 m et une Lumière faible sur 9 m de plus, et les créatures qui vous voient subissent le Désavantage aux jets d’attaque contre vous. Toute créature dans la zone de Lumière vive, si elle vous voit alors que le pouvoir de la robe est activé, doit réussir un jet de sauvegarde de Sagesse DD 15 sous peine de subir l’état Étourdi jusqu’à ce que l’effet prenne fin.</p>'),
  (1464, 38, 3, 0, NULL),
  (1465, 38, 4, 0, '<p>Ce sac, qui ressemble de prime abord à un sac sans fond, est en réalité la gueule par laquelle s’alimente une gigantesque créature extradimensionnelle. Retourner le sac comme un gant obstrue l’orifice.</p><p>La créature extradimensionnelle attachée au sac a conscience de tout ce qui est placé à l’intérieur. Toute matière d’origine animale ou végétale placée en totalité dans le sac est dévorée et perdue à jamais. Quand une partie d’une créature vivante est placée dans le sac, comme cela se produit lorsque l’on plonge la main à l’intérieur, cette créature a 50 % de risque d’être happée à l’intérieur. Une créature à l’intérieur du sac peut entreprendre une action pour tenter de s’échapper, ce qui lui demande de réussir un test de Force (Athlétisme) DD 15. Une autre créature peut entreprendre une action pour plonger le bras dans le sac afin d’en extraire une créature, ce qui lui demande de réussir un test de Force (Athlétisme) DD 20, à la condition de ne pas avoir été d’abord happée elle-même par le sac. Toute créature qui commence son tour à l’intérieur du sac est dévorée et son corps est détruit.</p><p>Les objets inanimés peuvent être stockés dans le sac, qui peut contenir 30 litres de matière inerte. Cependant, une fois par jour, le sac avale tous les objets qu’il contient et les recrache sur un autre plan d’existence. Le MJ détermine l’heure et le plan d’existence.</p><p>Le sac est détruit s’il est troué ou déchiré. Tout son contenu est alors transporté vers un lieu aléatoire du Plan Astral.</p>'),
  (1466, 38, 2, 0, '<p>L’espace de stockage de ce sac est considérablement plus grand que le laissent penser ses dimensions extérieures : 1,20 m de profondeur pour 60 cm de section. Le sac peut en fait contenir jusqu’à 250 kg, pour un volume maximal de 1 800 litres. Il pèse 2,5 kg quel que soit son contenu. Récupérer un objet dans le sac nécessite l’action Utilisation.</p><p>S’il est surchargé, troué ou déchiré, il est détruit. Son contenu est alors disséminé sur le Plan Astral. Si le sac est retourné comme un gant, son contenu se déverse sans que rien ne se brise, mais le sac doit être remis à l’endroit avant de pouvoir être réutilisé. Le sac contient suffisamment d’air pour 10 minutes de ventilation, divisées par le nombre de créatures qui respirent à l’intérieur.</p><p>Placer un sac sans fond dans l’espace extradimensionnel créé par un havresac magique, un puits portable ou tout autre objet comparable détruit instantanément les deux objets et ouvre un portail vers le Plan Astral. Ce portail s’ouvre à l’endroit où l’objet a été placé dans l’autre. Toute créature située dans une Sphère de 3 m de rayon centrée sur le portail est aspirée pour se retrouver en un lieu aléatoire du Plan Astral. Le portail se referme alors. Il est à sens unique et ne peut pas être rouvert.</p>'),
  (1467, 38, 5, 1, '<p>Ce médaillon en forme de scarabée offre trois bénéfices lorsque vous le portez.</p><p><b>Défense.</b> Vous recevez un bonus de +1 à la classe d’armure.</p><p><b>Préservation.</b> Le scarabée dispose de 12 charges. Si vous ratez un jet de sauvegarde contre un sort de Nécromancie ou un effet néfaste émanant d’un Mort-vivant, vous pouvez jouer votre Réaction pour dépenser 1 charge et transformer l’échec au JS en réussite. Le scarabée tombe en poussière, détruit à jamais, lorsque sa dernière charge est dépensée.</p><p><b>Résistance aux sorts.</b> Vous avez l’Avantage aux jets de sauvegarde contre les sorts.</p>'),
  (1529, 41, 4, 1, '<p>Tant que vous tenez ce sceptre, vous pouvez jouer votre Réaction pour absorber un sort qui ne cible que vous et ne produit pas de zone d’effet. L’effet du sort absorbé est annulé et son énergie est stockée dans le sceptre (mais pas le sort lui-même). L’énergie est du même niveau que le sort à son incantation. Un sort ainsi annulé se dissipe sans produire d’effet ; toutes les ressources engagées par l’incantation sont gaspillées. Le sceptre peut absorber et stocker jusqu’à 50 niveaux d’énergie au cours de son existence. Une fois que ce sceptre a absorbé 50 niveaux d’énergie, il ne peut plus en absorber. Si vous êtes la cible d’un sort que le sceptre ne peut pas stocker, l’objet n’a aucun effet sur ce sort.</p><p>En vous harmonisant avec le sceptre, vous savez combien de niveaux d’énergie il a absorbés au cours de son existence et combien de niveaux d’énergie de sort sont actuellement stockés à l’intérieur.</p><p>Si vous êtes un incantateur et tenez le sceptre, vous pouvez convertir l’énergie qu’il contient en emplacements de sort afin de lancer des sorts que vous avez préparés ou que vous connaissez. Vous ne pouvez créer que des emplacements de sort d’un niveau inférieur ou égal à vos propres emplacements de sort, sans dépasser le 5e niveau. Vous utilisez les niveaux stockés à la place de vos propres emplacements, mais pour tout le reste, ces sorts sont lancés normalement. Vous pouvez par exemple utiliser 3 niveaux stockés dans le sceptre comme emplacement de sort du 3e niveau.</p><p>Un sceptre nouvellement découvert contient généralement 1d10 niveaux d’énergie de sort. Un sceptre qui ne peut plus absorber l’énergie des sorts et qui n’a plus d’énergie en stock devient non magique.</p>'),
  (1530, 41, 5, 1, '<p>Les jets d’attaque et de dégâts que vous effectuez avec ce sceptre à ailettes, considéré comme une masse d’armes magique, reçoivent un bonus de +3. Le sceptre possède des propriétés associées à six boutons différents étagés le long du manche. Il est aussi doté de trois autres propriétés, détaillées ci-après.</p><p><b>Boutons-poussoirs.</b> Vous pouvez appuyer sur l’un des boutons suivants par une action Bonus. L’effet d’un bouton dure jusqu’à ce que vous pressiez un autre bouton ou jusqu’à ce que vous réappuyiez sur le même bouton, ce qui fait revenir le sceptre à sa forme normale.</p><p><b>Bouton 1.</b> Une lame ardente surgit de l’extrémité opposée à la tête à ailettes du sceptre. Les flammes émettent une Lumière vive dans un rayon de 12 m et une Lumière faible sur 12 m de plus. La lame fonctionne comme une épée longue ou une épée courte magique (choisissez) qui inflige 2d6 dégâts de feu supplémentaires si l’attaque touche.</p><p><b>Bouton 2.</b> La tête à ailettes du sceptre se replie et laisse la place à deux lames en croissant de lune ; les jets d’attaque et de dégâts que vous effectuez avec cette arme considérée comme une hache d’armes magique reçoivent un bonus de +3.</p><p><b>Bouton 3.</b> La tête à ailettes du sceptre se replie et un fer de lance surgit de l’extrémité tandis que le manche s’allonge pour former une hampe de 1,80 m ; les jets d’attaque et de dégâts que vous effectuez avec cette arme considérée comme une lance magique reçoivent un bonus de +3.</p><p><b>Bouton 4.</b> Le sceptre se transforme en un mât d’escalade pouvant atteindre 15 m de long (vous spécifiez la longueur). Les boutons du sceptre restent à votre portée. Ce mât s’ancre dans toute surface aussi dure que le granit, par l’intermédiaire d’une pointe à la base et de trois crochets au sommet. Des barreaux horizontaux de 7,5 cm de long se déploient sur les côtés, à 30 cm d’écart, formant une échelle. Le mât supporte un poids maximal de 2 000 kg. Un poids excessif ou un ancrage insuffisant font revenir le sceptre à sa forme normale. Bouton 5. Le sceptre se transforme en bélier portable qui octroie à son utilisateur un bonus de +10 aux tests de Force (Athlétisme) visant à défoncer une porte, une barricade ou toute autre barrière. Bouton 6. Le sceptre retrouve ou conserve son aspect normal et indique le nord magnétique. (Rien ne se passe si cette fonction du sceptre est utilisée en un lieu dépourvu de nord magnétique.) Le sceptre vous fournit en outre une estimation de votre profondeur sous terre ou de votre altitude à la surface.</p><p><b>Absorption de vie.</b> Lorsque vous touchez une créature avec une attaque de corps à corps en utilisant le sceptre, vous pouvez soumettre la cible à un jet de sauvegarde de Constitution DD 17. En cas d’échec, la cible subit 4d6 dégâts nécrotiques supplémentaires et vous récupérez autant de points de vie que la moitié des dégâts nécrotiques ainsi infligés. Une fois utilisée, cette propriété ne peut plus resservir jusqu’à l’aube suivante.</p><p><b>Paralysie.</b> Lorsque vous touchez une créature avec une attaque de corps à corps en utilisant le sceptre, vous pouvez soumettre la cible à un jet de sauvegarde de Constitution DD 17. En cas d’échec, la cible subit l’état Paralysé pendant 1 minute. La cible réitère le JS à la fin de chacun de ses tours et met un terme à l’effet sur elle-même en cas de réussite. Une fois utilisée, cette propriété ne peut plus resservir jusqu’à l’aube suivante.</p><p><b>Terreur.</b> Tant que vous brandissez le sceptre, vous pouvez entreprendre l’action Magie pour soumettre chaque créature que vous voyez dans un rayon de 9 m à un jet de sauvegarde de Sagesse DD 17. En cas d’échec, la cible subit l’état Effrayé pendant 1 minute. Chaque cible Effrayée réitère le JS à la fin de chacun de ses tours et met un terme à l’effet sur elle-même en cas de réussite. Une fois utilisée, cette propriété ne peut plus resservir jusqu’à l’aube suivante.</p>'),
  (1531, 41, 5, 1, '<p>Le sceptre dispose de 5 charges. Lorsque vous le tenez, vous pouvez lancer l’un des sorts suivants par son intermédiaire : guérison (dépense 1 charge) ou résurrection (dépense 5 charges).</p><p>Le sceptre récupère quotidiennement 1 charge dépensée, à l’aube. Si vous dépensez la dernière charge, lancez 1d20. Sur un résultat de 1, le sceptre disparaît dans une explosion radiante inoffensive.</p>'),
  (1532, 41, 4, 0, '<p>Quand vous tenez ce sceptre, vous pouvez entreprendre l’action Magie pour l’activer. Le sceptre vous transporte alors instantanément, ainsi qu’un maximum de 199 autres créatures consentantes que vous voyez, vers un demi-plan. Choisissez la forme prise par ce demi-plan. Il peut s’agir d’un jardin tranquille, d’une taverne joyeuse, d’un immense palais, d’une île tropicale, d’un carnaval fantastique ou de tout autre lieu tiré de votre imagination. Quelle que soit sa nature, le demi-plan contient suffisamment d’eau et de nourriture pour subvenir aux besoins de ses visiteurs, et son environnement ne peut pas nuire à ses occupants. Tout ce avec quoi il est possible d’y interagir n’existe que là-bas. Une fleur cueillie dans un jardin, par exemple, disparaît si elle est emportée hors du demi-plan.</p><p>Pour chaque heure passée dans le demi-plan, un visiteur récupère autant de points de vie que s’il avait dépensé 1 dé de vie. En outre, les créatures ne vieillissent pas pendant leur séjour, bien que le temps s’écoule normalement. Les visiteurs peuvent y rester un total de 200 jours divisés par le nombre de créatures présentes (arrondir à l’inférieur).</p><p>Quand le temps est écoulé ou si vous consacrez l’action Magie à mettre fin à l’effet, tous les visiteurs réapparaissent à l’emplacement qu’ils occupaient lorsque vous avez activé le sceptre, ou à défaut dans l’espace inoccupé le plus proche. Une fois utilisée, cette propriété ne peut plus resservir avant que 10 jours ne se soient écoulés.</p>'),
  (1533, 41, 3, 1, '<p>Vous pouvez entreprendre l’action Magie pour brandir le sceptre et exiger l’obéissance de toutes les créatures de votre choix parmi celles que vous voyez dans un rayon de 36 m. Chaque cible doit réussir un jet de sauvegarde de Sagesse DD 15 sous peine de subir l’état Charmé pendant 8 heures. Tant qu’elle est Charmée de la sorte, une créature se fie à votre autorité. Si elle est blessée par vous ou vos alliés, ou s’il lui est donné l’ordre de commettre un acte contraire à sa nature, une cible cesse d’être ainsi Charmée. Une fois utilisée, cette propriété ne peut plus resservir avant l’aube suivante.</p>'),
  (1534, 41, 4, 1, '<p>Ce sceptre possède les propriétés suivantes. Vigilance. Tant que vous tenez ce sceptre, vous avez l’Avantage aux tests de Sagesse (Perception) et aux jets d’Initiative.</p><p><b>Sorts.</b> En tenant le sceptre, vous pouvez lancer les sorts suivants par son intermédiaire :</p><ul><li>détection du mal et du bien</li><li>détection de la magie</li><li>détection du poison et des maladies</li><li>détection de l’invisibilité</li></ul><p><b>Aura de protection.</b> Au prix de l’action Magie, vous pouvez planter le manche du sceptre dans le sol, auquel cas sa tête émet une Lumière vive sur un rayon de 18 m et une Lumière faible sur 18 m de plus. Dans cette Lumière vive, vous et vos alliés recevez un bonus de +1 à la CA et aux jets de sauvegarde, et vous percevez la position de toute créature Invisible également présente dans la Lumière vive.</p><p>La tête du sceptre cesse de briller et l’effet prend fin au bout de 10 minutes (plus tôt si une créature consacre l’action Magie à l’arracher du sol). Une fois utilisée, cette propriété ne peut plus resservir jusqu’à l’aube suivante.</p>'),
  (1535, 41, 2, 0, '<p>Ce sceptre en fer présente un poussoir à une extrémité. Consacrer l’action Utilisation à appuyer sur le poussoir a pour conséquence de figer magiquement le sceptre sur place. Jusqu’à ce que vous-même ou une autre créature consacriez l’action Utilisation à appuyer de nouveau sur le poussoir, le sceptre ne bouge pas, même si sa position défie les lois de la gravité. Le sceptre peut supporter un maximum de 4 000 kg. Un poids supérieur provoque la désactivation du sceptre et sa chute. Une créature peut consacrer l’action Utilisation à effectuer un test de Force (Athlétisme) DD 30, et déplace le sceptre figé d’un maximum de 3 m en cas de réussite.</p>'),
  (1468, 38, 5, 0, '<p>Ce tube contient un liquide laiteux qui dégage une forte odeur d’alcool. Lorsqu’on le découvre, un tel récipient contient 1d6 + 1 doses de 30 g.</p><p>Vous pouvez entreprendre l’action Utilisation pour verser une ou plusieurs doses sur une surface à portée d’allonge. Le liquide dissout instantanément jusqu’à 30 x 30 cm d’adhésif qu’il touche, y compris de la colle universelle.</p>'),
  (1469, 38, 5, 0, NULL),
  (1470, 38, 5, 0, '<p>Cet objet ressemble de prime abord à un baril hermétique en fer d’un poids de 250 kg. Le tonneau est doté d’un loquet caché que l’on trouve à condition de réussir un test d’Intelligence (Investigation) DD 20. Actionner le loquet déverrouille une écoutille sur l’une des faces rondes du baril, ce qui permet à deux créatures de taille M ou inférieure de ramper à l’intérieur. Dix leviers sont disposés en ligne au fond du baril, chacun en position neutre et que l’on peut actionner vers le haut ou le bas. Lorsque certains leviers sont actionnés, l’appareil se transforme pour prendre l’apparence d’un homard géant.</p><p>Le submersible du Crabe est un objet de taille G avec le profil suivant : CA 20, 200 pv, Vitesse 9 m, nage 9 m (ou 0 m pour les deux si les pattes ne sont pas déployées) ; Immunité contre les dégâts psychiques et de poison.</p><p>Pour être utilisé comme véhicule, le submersible nécessite un pilote. Tant que la trappe est fermée, le compartiment est étanche à l’air et à l’eau. Le compartiment contient suffisamment d’air pour 10 heures de ventilation, divisées par le nombre de créatures qui respirent à l’intérieur.</p><p>Leviers du submersible</p><p>Levier Haut 1 Les pattes se déploient et le submersible est apte à la marche comme à la nage.</p><p>2 Le volet du hublot avant s’ouvre. 3 Les volets des hublots latéraux s’ouvrent (deux par côté). 4 Deux pinces se déploient depuis les côtés, à l’avant du submersible. 5 Chaque pince déployée effectue l’attaque de corps à corps suivante : +8 pour toucher, allonge 1,50 m. Touché : 7 (2d6) dégâts contondants. 6 Le submersible marche ou nage vers l’avant à condition que ses pattes soient déployées. 7 Le submersible pivote de 90 degrés vers la gauche à condition que ses pattes soient déployées. 8 Des yeux mécaniques émettent une Lumière vive dans un rayon de 9 m et une Lumière faible sur 9 m de plus. 9 Le submersible descend de 6 m s’il évolue dans l’élément liquide. 10 L’écoutille arrière s’ouvre.</p><p>Bas Les pattes se rétractent, ce qui réduit la Vitesse et la Vitesse de nage du submersible à 0 m et l’empêche de bénéficier d’un quelconque bonus de vitesse. Le volet du hublot avant se ferme. Les volets des hublots latéraux se ferment (deux par côté). Les pinces se rétractent.</p><p>Chaque pince déployée effectue l’attaque de corps à corps suivante : +8 pour toucher, allonge 1,50 m. Touché : La cible subit l’état Agrippé (évasion DD 15). Le submersible marche ou nage vers l’arrière à condition que ses pattes soient déployées. Le submersible pivote de 90 degrés vers la droite à condition que ses pattes soient déployées. La lumière s’éteint.</p><p>Le submersible remonte de 6 m s’il évolue dans l’élément liquide. L’écoutille arrière se ferme hermétiquement.</p><p>Le submersible flotte sur l’eau. Il peut également être immergé jusqu’à une profondeur de 270 m. Plus profondément, le véhicule, soumis à une trop forte pression, subit chaque minute 2d6 dégâts contondants.</p><p>Une créature dans le compartiment peut consacrer l’action Utilisation à activer un ou deux des leviers du submersible vers le haut ou le bas. Après chaque utilisation, un levier revient en position neutre. Chaque levier, de gauche à droite, fonctionne comme indiqué dans la table « Leviers du submersible ».</p>'),
  (1471, 38, 5, 1, '<p>Tant que vous tenez ou portez ce talisman, vous avez l’Avantage à tout test d’Intelligence (Arcanes) visant à contrôler une sphère d’annihilation. En outre, lorsque vous commencez votre tour en contrôlant une sphère d’annihilation, vous pouvez entreprendre l’action Magie pour la déplacer, en mètres, d’un maximum de 3 plus le triple de votre modificateur d’Intelligence. Ce déplacement n’est pas nécessairement en ligne droite.</p>'),
  (1472, 38, 5, 1, '<p><em>Harmonisation requise avec un Clerc ou Paladin</em></p><p>Ce talisman est un puissant symbole de bonté. Un Fiélon ou un Mort-vivant qui touche le talisman subit 8d6 dégâts radiants, et en subit autant chaque fois qu’il termine son tour en tenant ou en portant le talisman.</p><p><b>Réprimande pure.</b> Le talisman dispose de 7 charges. Lorsque vous portez ou tenez le talisman, vous pouvez entreprendre l’action Magie pour dépenser 1 charge et cibler une créature que vous voyez en contact avec le sol dans un rayon de 36 m. Une faille ardente s’ouvre sous la cible, qui effectue un jet de sauvegarde de Dextérité DD 20. Si la cible est un Fiélon ou un Mortvivant, elle subit le Désavantage au JS. En cas d’échec, elle tombe dans la faille, ce qui la détruit sans en laisser la moindre trace. En cas de réussite, la cible n’est pas précipitée dans la faille mais l’épreuve lui inflige 4d6 dégâts psychiques. Dans un cas comme dans l’autre, la faille se referme alors, ne laissant aucune trace de son existence. Lorsque vous dépensez sa dernière charge, le talisman se désagrège en particules de lumière dorée, détruit à jamais.</p><p><b>Symbole sacré.</b> Vous pouvez utiliser le talisman comme symbole sacré. Vous recevez un bonus de +2 aux jets d’attaque de sort lorsque vous le portez ou le tenez.</p>'),
  (1473, 38, 5, 1, '<p>Cet objet symbolise la quintessence du mal. Toute créature autre qu’un Fiélon ou un Mort-vivant qui touche le talisman subit 8d6 dégâts nécrotiques, et en subit autant chaque fois qu’elle termine son tour en tenant ou en portant le talisman.</p><p><b>Fin irrévocable.</b> Le talisman dispose de 6 charges. Lorsque vous portez ou tenez le talisman, vous pouvez entreprendre l’action Magie pour dépenser 1 charge et cibler une créature que vous voyez en contact avec le sol dans un rayon de 36 m. Une faille ardente s’ouvre sous la cible, qui effectue un jet de sauvegarde de Dextérité DD 20. Si la cible est un Céleste, elle subit le</p><p><b>Désavantage au JS.</b> En cas d’échec, elle tombe dans la faille, ce qui la détruit sans en laisser la moindre trace. En cas de réussite, la cible n’est pas précipitée dans la faille mais l’épreuve lui inflige 4d6 dégâts psychiques. Dans un cas comme dans l’autre, la faille se referme alors, ne laissant aucune trace de son existence. Lorsque vous dépensez sa dernière charge, le talisman se dissout en limon malodorant, détruit à jamais.</p><p><b>Symbole sacré.</b> Vous pouvez utiliser le talisman comme symbole sacré. Vous recevez un bonus de +2 aux jets d’attaque de sort lorsque vous le portez ou le tenez.</p>'),
  (1478, 38, 2, 0, '<p>Cette boîte contient un jeu de cartes. Un jeu complet se compose de 34 cartes (ou « lames ») : 32 représentent des créatures spécifiques, les deux dernières ont une surface réfléchissante. Il manque généralement 1d20 − 1 cartes à un jeu trouvé comme trésor.</p><p>La magie du tarot n’opère que si les lames sont piochées au hasard. Vous pouvez consacrer l’action Magie à piocher une lame au hasard et à la jeter au sol, en un point situé dans un rayon de 9 m de vous. L’illusion d’une créature, déterminée par un tirage sur la table « Tarot fantasmagorique », se forme au-dessus de la carte ainsi jetée et persiste jusqu’à dissipation. La créature illusoire créée par la lame ressemble à une vraie créature de son espèce et se comporte comme telle, mais elle est parfaitement inoffensive. Tant que vous êtes dans un rayon de 36 m de la créature illusoire et que vous la voyez, vous pouvez consacrer l’action Magie à la déplacer en n’importe quel point situé dans un rayon de 9 m de sa carte d’origine.</p><p>Toute interaction physique avec la créature illusoire percera l’illusion, car elle est intangible. Une créature qui entreprend l’action Étude afin d’inspecter visuellement la créature illusoire perce l’illusion pour peu qu’elle réussisse un test d’Intelligence (Investigation) DD 15. L’illusion persiste jusqu’à sa dissipation (par le biais du sort dissipation de la magie ou de tout effet comparable) ou que sa carte soit déplacée. Lorsque l’illusion prend fin, l’image de la carte s’efface et cette carte ne peut pas être réutilisée.</p><p>Tarot fantasmagorique</p><p>1d100 Illusion* 01–03 Archimage 04–06 Assassin 07–09 Basilic 10–12 Berserker 13–15 Capitaine bandit 16–18 Chevalier 19–21 Combattant gnoll 22–24 Combattant gobelin 25–27 Combattant gobelours 28–30 Combattant hobgobelin 31–33 Combattant kobold 34–36 Dragon rouge adulte 37–39 Druide 40–42 Ecclésiastique 43–45 Érinye 46–48 Ettin 49–51 Géant des collines 52–54 Géant des nuages 55–57 Géant du feu 58–60 Géant du givre 61–63 Golem de fer 64–66 Guenaude nocturne 67–69 Incube 70–72 Liche 73–75 Méduse 76–78 Naga gardien 79–81 Ogre 82–84 Oni 85–87 Succube 88–90 Troll 91–93 Vétéran 94–96 Vouivre 97–00 La personne qui a tiré la carte</p><p>*Les profils de ces créatures (hormis celui de la personne qui a tiré la carte) figurent dans la section « Monstres ».</p>'),
  (1479, 38, 5, 0, NULL),
  (1481, 38, 4, 0, '<p>Ce livre aux inscriptions chargées de magie dispense de précieux conseils sur la façon d’influencer et de captiver l’auditoire. Si vous consacrez 48 heures sur une période maximale de 6 jours à étudier le contenu de l’ouvrage et à le mettre en pratique, votre valeur de Charisme augmente de 2, jusqu’à un maximum de 30. Le manuel perd alors sa magie, mais la retrouve après un siècle.</p>'),
  (1482, 38, 4, 0, '<p>Ce livre aux inscriptions chargées de magie propose de précieux exercices d’intuition et de perspicacité. Si vous consacrez 48 heures sur une période maximale de 6 jours à étudier le contenu de l’ouvrage et à le mettre en pratique, votre valeur de Sagesse augmente de 2, jusqu’à un maximum de 30. Le manuel perd alors sa magie, mais la retrouve après un siècle.</p>'),
  (1480, 38, 4, 0, '<p>Ce livre aux inscriptions chargées de magie recèle de précieux exercices de mémoire et de logique. Si vous consacrez 48 heures sur une période maximale de 6 jours à étudier le contenu de l’ouvrage et à le mettre en pratique, votre valeur d’Intelligence augmente de 2, jusqu’à un maximum de 30. Le manuel perd alors sa magie, mais la retrouve après un siècle.</p>'),
  (1246, 34, 2, 1, '<p>Cette arme magique dispose de 3 charges et récupère quotidiennement 1d3 charges dépensées, à l’aube. Tant que vous la portez, vous pouvez dépenser 1 charge pour lancer le sort domination de bête (DD de sauvegarde 15) par son biais sur une Bête dotée d’une Vitesse de nage.</p>'),
  (1242, 34, 3, 0, '<p>Vous recevez un bonus de +1 aux jets d’attaque et de dégâts effectués avec cette arme magique.</p><p>L’arme inflige 3d6 dégâts supplémentaires du type de l’arme si la cible est un Dragon.</p>'),
  (1243, 34, 3, 0, '<p>Vous recevez un bonus de +1 aux jets d’attaque et de dégâts effectués avec cette arme magique.</p><p>Quand vous touchez un Géant avec cette arme, il subit 2d6 dégâts supplémentaires du type associé à l’arme et doit réussir un jet de sauvegarde de Force DD 15 sous peine de subir l’état À terre.</p>'),
  (1483, 38, 2, 0, '<p>Au prix de l’action Magie, vous ouvrez ou refermez cette urne.</p><p>L’ouvrir provoque l’expulsion d’une fumée épaisse qui génère un nuage sous forme d’une Émanation de 18 m centrée sur l’urne. La zone enfumée est à Visibilité nulle.</p><p>Chaque minute que l’urne reste ouverte, la taille de l’Émanation augmente de 3 m jusqu’à avoir atteint sa taille maximale de 36 m.</p><p>La fermeture de l’urne provoque l’immobilisation du nuage, qui se disperse au bout de 10 minutes. Un vent fort (tel que celui créé par le sort bourrasque) disperse le nuage en 1 minute.</p>'),
  (1244, 34, 5, 1, '<p><em>Harmonisation requise avec un Paladin</em></p><p>Vous recevez un bonus de +3 aux jets d’attaque et de dégâts effectués avec cette arme magique. Quand vous touchez un Fiélon ou un Mort-vivant avec cette arme, la créature subit 2d10 dégâts radiants supplémentaires.</p><p>Tant que vous tenez l’arme au clair, elle crée une Émanation de 3 m centrée sur vous. Vous-même et toutes les créatures de l’Émanation qui vous sont Amicales bénéficiez de l’Avantage aux jets de sauvegarde contre les sorts et autres effets magiques. Si vous disposez de 17 niveaux ou plus dans la classe de Paladin, la taille de cette Émanation passe à 9 m.</p>'),
  (1245, 34, 4, 1, '<p>Vous recevez un bonus de +2 aux jets d’attaque et de dégâts effectués avec cette arme magique.</p><p>Vol de vie. L’arme dispose de 1d8 + 1 charges. Lorsque vous attaquez une créature dotée de moins de 100 points de vie avec cette arme et obtenez un 20 sur le d20 du jet d’attaque, la créature doit réussir un jet de sauvegarde de Constitution DD 15 sous peine de mourir sur-le-champ, l’épée lui arrachant sa force vitale. Les Artificiels et les Morts-vivants réussissent automatiquement ce JS. L’arme perd 1 charge si la créature est tuée. Elle perd cette propriété quand toutes ses charges ont été dépensées.</p>');
